/* Card set: Inventions (built from the approved roster.csv by the Inventions build).
   380 cards: Foundational, Industrial, Medicine, Household, Communication,
   Computing, Accident, Patent. Art: public-domain patent drawings and period
   photos wherever a good one exists, modern photos otherwise — every image
   eyeball-verified under the live-site referer audit. */
CardSets.register({"id": "inventions", "name": "Inventions", "code": "INVENT", "description": "380 cards celebrating the inventions that built the modern world — ancient foundations, industrial giants, happy accidents, and the weird patents that never stood a chance.", "theme": {"primary": "#e8a33d", "secondary": "#1d3557", "artBackground": "#f3ecd9", "artFit": "contain"}, "pack": {"name": "Inventions Pack", "emblem": "💡", "skin": "inventions", "slots": [{"count": 5, "label": "Common", "odds": {"common": 100}}, {"count": 2, "label": "Uncommon", "odds": {"uncommon": 100}}, {"count": 1, "label": "Wild card", "odds": {"common": 55, "uncommon": 30, "rare": 12, "epic": 3}}, {"count": 1, "label": "Rare or better (guaranteed)", "odds": {"rare": 81.8, "epic": 14, "legendary": 4, "chase": 0.2}}]}, "cards": [{"name": "The Wheel", "rarity": "chase", "id": "the-wheel", "subtitle": "Foundational", "details": "First appearing in Mesopotamia and Europe over 5,000 years ago, the wheel turned sledges into carts and reshaped transport, trade and pottery.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Spoked%20wheel%20from%20Arokalja.jpg?width=1024"}, {"name": "Movable-Type Printing Press", "rarity": "chase", "id": "movable-type-printing-press", "subtitle": "Foundational", "details": "Movable type began earlier in China and Korea; Gutenberg's press system, c. 1440, combined it with screw presses to transform European printing.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Printing%20press%2004.jpg?width=1024"}, {"name": "Steam Engine", "rarity": "chase", "id": "steam-engine", "subtitle": "Industrial", "details": "Newcomen built an early steam engine in 1712; Watt's separate condenser made the design efficient and practical.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Maquina_vapor_Watt_ETSIIM.jpg?width=1024"}, {"name": "Incandescent Light Bulb", "rarity": "chase", "id": "incandescent-light-bulb", "subtitle": "Industrial", "details": "Swan demonstrated an early bulb in England; Edison patented a practical, long-lasting bulb and the system to power it.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Gluehlampe_01_KMJ.png?width=1024"}, {"name": "Airplane", "rarity": "chase", "id": "airplane", "subtitle": "Industrial", "details": "The Wright brothers' 1903 Flyer is widely credited with the first sustained, controlled powered flight.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/First_flight2.jpg?width=1024"}, {"name": "Automobile", "rarity": "chase", "id": "automobile", "subtitle": "Industrial", "details": "Karl Benz patented the Motorwagen in 1886, a three-wheeled carriage driven by a gasoline engine.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Benz_Patent-Motorwagen_Nr_2.jpg?width=1024"}, {"name": "Telephone", "rarity": "chase", "id": "telephone", "subtitle": "Communication", "details": "Bell patented the telephone in 1876; Meucci built an earlier voice device and Gray filed the same day.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Alexander_Graham_Bell%27s_Telephone_Patent_Drawing_and_Oath_-_NARA_-_302052_%28page_2%29.jpg?width=1024"}, {"name": "Transistor", "rarity": "chase", "id": "transistor", "subtitle": "Computing", "details": "Bardeen, Brattain and Shockley demonstrated the transistor at Bell Labs in 1947; it shrank electronics to pocket size.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Replica-of-first-transistor.jpg?width=1024"}, {"name": "World Wide Web", "rarity": "chase", "id": "world-wide-web", "subtitle": "Computing", "details": "Tim Berners-Lee built the first website at CERN in 1991 and gave the web away free two years later.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/First_Web_Server.jpg?width=1024"}, {"name": "Penicillin", "rarity": "chase", "id": "penicillin", "subtitle": "Accident", "details": "Fleming noticed mould killing bacteria in 1928; Florey and Chain's team later turned that accident into a usable drug.", "image": "https://upload.wikimedia.org/wikipedia/commons/1/1c/Penicillium_notatum.jpg"}, {"name": "Paper", "rarity": "legendary", "id": "paper", "subtitle": "Foundational", "details": "Papermaking is credited to Cai Lun in China, c. 105 CE, refining earlier hemp papers into a cheap, light writing surface for the world.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Cai-lun.jpg?width=1024"}, {"name": "Magnetic Compass", "rarity": "legendary", "id": "magnetic-compass", "subtitle": "Foundational", "details": "Chinese navigators used lodestone compasses by the Song era; the needle compass spread to ships worldwide and remade ocean navigation.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Chinese%20Mariner%27s%20Compass%20c.%201760%20%28NAV0240%29%2C%20National%20Maritime%20Museum.JPG?width=1024"}, {"name": "Gunpowder", "rarity": "legendary", "id": "gunpowder", "subtitle": "Foundational", "details": "Developed in China by the 9th century, this mix of saltpetre, charcoal and sulphur spread from fireworks to firearms across the world.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Fire%20arrows.jpg?width=1024"}, {"name": "The Plow", "rarity": "legendary", "id": "the-plow", "subtitle": "Foundational", "details": "From scratch ploughs in Mesopotamia to iron mouldboard designs, the plow broke heavier soils and underpinned farming surpluses for millennia.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Horse%20Ploughing%20%287%29%20%288069915464%29.jpg?width=1024"}, {"name": "Sailing", "rarity": "legendary", "id": "sailing", "subtitle": "Foundational", "details": "Lateen and square sails let ships harness wind instead of oars, extending voyages across the Mediterranean, Indian Ocean and beyond.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Old%20and%20New%20%28Imagicity%201020%29.jpg?width=1024"}, {"name": "Glassblowing", "rarity": "legendary", "id": "glassblowing", "subtitle": "Foundational", "details": "Glassblowing emerged in the Syro-Palestinian region in the 1st century BCE, making glass vessels fast, cheap and widely available.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Damascene%20glass%20blower%2001.jpg?width=1024"}, {"name": "Photography", "rarity": "legendary", "id": "photography", "subtitle": "Industrial", "details": "Nicéphore Niépce made the first lasting photograph in the 1820s; Daguerre's process brought it to the public.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Roger_Fenton%27s_waggon.jpg?width=1024"}, {"name": "Dynamo", "rarity": "legendary", "id": "dynamo", "subtitle": "Industrial", "details": "Faraday showed electromagnetic induction in 1831; the dynamo turned motion into electric current on demand.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/DynamoElectricMachinesEndViewPartlySection_USP284110.png?width=1024"}, {"name": "Internal Combustion Engine", "rarity": "legendary", "id": "internal-combustion-engine", "subtitle": "Industrial", "details": "Burning fuel inside the cylinder itself, this compact engine powered cars, planes and machines of every kind.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Four_stroke_engine_diagram.jpg?width=1024"}, {"name": "Vaccination", "rarity": "legendary", "id": "vaccination", "subtitle": "Medicine", "details": "Edward Jenner used cowpox in 1796 to protect against smallpox; variolation with the disease itself was older and riskier.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Young_girl_about_to_receive_a_vaccine_in_her_upper_arm_%2848545990252%29.jpg?width=1024"}, {"name": "Refrigerator", "rarity": "legendary", "id": "refrigerator", "subtitle": "Household", "details": "Vapour-compression cooling, refined by many inventors in the 1920s, finally let households keep food cold without daily ice deliveries.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Open_refrigerator_with_food_at_night.jpg?width=1024"}, {"name": "Washing Machine", "rarity": "legendary", "id": "washing-machine", "subtitle": "Household", "details": "Electric washers from the early 1900s mechanised laundry day, replacing hours of hand-scrubbing with a motor, an agitator and a wringer.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/LG_%EB%93%9C%EB%9F%BC%EC%84%B8%ED%83%81%EA%B8%B0%EC%99%80_%EC%8B%9D%EA%B8%B0%EC%84%B8%EC%B2%99%EA%B8%B0%2C_%EC%98%81%EA%B5%AD%EC%84%9C_%EB%AC%BC%EC%82%AC%EC%9A%A9_%ED%9A%A8%EC%9C%A8_%EC%B5%9C%EC%9A%B0%EC%88%98_%EC%A0%9C%ED%92%88_%EC%88%98%EC%83%81.jpg?width=1024"}, {"name": "Air Conditioning", "rarity": "legendary", "id": "air-conditioning", "subtitle": "Household", "details": "Willis Carrier built his 1902 apparatus to control humidity in a printing plant; cooling people, not just paper, came soon after.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/MITSUBISHI_ELECTRIC_WINDOW_TYPE_AIR_CONDITIONER_OUTDOOR_UNIT.jpg?width=1024"}, {"name": "Vacuum Cleaner", "rarity": "legendary", "id": "vacuum-cleaner", "subtitle": "Household", "details": "Hubert Cecil Booth's 1901 machine used suction to draw dust into a filter, the principle every carpet cleaner still follows today.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Numatic_Henry_vacuum_cleaner_%283308986870%29_%28cropped%29.jpg?width=1024"}, {"name": "Flush Toilet", "rarity": "legendary", "id": "flush-toilet", "subtitle": "Household", "details": "Flushing designs date to the 1590s; Victorian plumbers like Thomas Crapper popularised reliable valves and traps, not the idea itself.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Toilet_photo.jpg?width=1024"}, {"name": "Radio", "rarity": "legendary", "id": "radio", "subtitle": "Communication", "details": "Marconi commercialised wireless radio; Tesla held key patents, and many experimenters shared its birth.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/EB1911_Telegraph_-_Marconi_transmitter-receiver_apparatus.jpg?width=1024"}, {"name": "Television", "rarity": "legendary", "id": "television", "subtitle": "Communication", "details": "Baird showed mechanical TV and Farnsworth sent the first electronic image in 1927; the rivals merged into TV.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/John_Logie_Baird_and_television_receiver.jpg?width=1024"}, {"name": "The Internet", "rarity": "legendary", "id": "the-internet", "subtitle": "Communication", "details": "ARPANET linked its first four computers in 1969; packet switching let networks grow into one Internet.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Arpanet_logical_map%2C_march_1977.png?width=1024"}, {"name": "Integrated Circuit", "rarity": "legendary", "id": "integrated-circuit", "subtitle": "Computing", "details": "Kilby and Noyce, working apart in 1958-59, each put a whole circuit on one chip; both are credited.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/EPROM_Microchip_SuperMacro.jpg?width=1024"}, {"name": "Stored-Program Computer", "rarity": "legendary", "id": "stored-program-computer", "subtitle": "Computing", "details": "The Manchester Baby ran the first stored program in 1948: instructions held in memory, like data.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/The-baby-replica-mosi-manchester-gt-britain-1.jpg?width=1024"}, {"name": "Analytical Engine", "rarity": "legendary", "id": "analytical-engine", "subtitle": "Computing", "details": "Babbage designed the Analytical Engine in the 1830s; Lovelace's notes on it included an early algorithm.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Analytical_engine_trial_model%2C_Charles_Babbage%2C_1834-1871_-_Science_Museum%2C_London_-_DSC05565.jpg?width=1024"}, {"name": "Post-it Note", "rarity": "legendary", "id": "post-it-note", "subtitle": "Accident", "details": "Silver's too-weak glue looked useless until Fry used it to anchor a bookmark — together they made the repositionable note.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/Sticky_Note_colors.jpg/1280px-Sticky_Note_colors.jpg"}, {"name": "Play-Doh", "rarity": "legendary", "id": "play-doh", "subtitle": "Accident", "details": "A putty sold to clean soot from wallpaper lost its market, then was reborn as the modelling compound in classroom tubs.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Playdoh.jpg?width=1024"}, {"name": "Potato Chips", "rarity": "legendary", "id": "potato-chips", "subtitle": "Accident", "details": "The story goes that Crum sliced potatoes paper-thin for a fussy diner in 1853 — historians doubt it, but Saratoga loved them.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/6/69/Potato-Chips.jpg/1280px-Potato-Chips.jpg"}, {"name": "Perpetual Motion Machine", "rarity": "legendary", "id": "perpetual-motion-machine", "subtitle": "Patent", "details": "For centuries, inventors chased a wheel that would turn forever for free. Physics said no; the patent office eventually demanded working models.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Perpetual%20motion%20wheels.jpg"}, {"name": "Leonardo's Ornithopter", "rarity": "legendary", "id": "leonardos-ornithopter", "subtitle": "Patent", "details": "Leonardo sketched a human-powered flying machine with flapping wings around 1487. It was never built in his lifetime, and could not have flown.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Design%20for%20a%20Flying%20Machine.jpg"}, {"name": "Lever", "rarity": "epic", "id": "lever", "subtitle": "Foundational", "details": "A rigid bar on a fulcrum multiplies force; Archimedes is said to have boasted he could move the Earth with a lever long enough.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Pince%20monseigneur.jpg?width=1024"}, {"name": "Aqueduct", "rarity": "epic", "id": "aqueduct", "subtitle": "Foundational", "details": "Roman aqueducts carried water tens of kilometres on gentle gradients of arches and channels to supply cities, baths and fountains.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Pont%20du%20Gard%20%2830%29.jpg?width=1024"}, {"name": "Roman Concrete", "rarity": "epic", "id": "roman-concrete", "subtitle": "Foundational", "details": "Roman builders mixed lime with volcanic ash to make concrete that could set underwater and endure in harbours and domes for centuries.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Dome%20Interior%20of%20the%20Pantheon%2C%20Rome.jpg?width=1024"}, {"name": "Astrolabe", "rarity": "epic", "id": "astrolabe", "subtitle": "Foundational", "details": "Refined in the Hellenistic and Islamic worlds, the astrolabe modelled the sky and let users tell time and find direction from the stars.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Astrolabe%2C%20Iran%2C%20undated%2C%20brass%20-%20Huntington%20Museum%20of%20Art%20-%20DSC04900.JPG?width=1024"}, {"name": "Mechanical Clock", "rarity": "epic", "id": "mechanical-clock", "subtitle": "Foundational", "details": "Weight-driven clocks with escapements appeared in Europe by the late 1200s, bringing regular hours to towns, towers and monasteries.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/St%20Ricarius%20Church%20%2856%29.JPG?width=1024"}, {"name": "Coinage", "rarity": "epic", "id": "coinage", "subtitle": "Foundational", "details": "Standardised coins, struck in Lydia by the 7th century BCE from electrum, made trade portable and trusted beyond weighed metal.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Izmir%20Archaeology%20museum%20Greek%20coins%205810.jpg?width=1024"}, {"name": "Woodblock Printing", "rarity": "epic", "id": "woodblock-printing", "subtitle": "Foundational", "details": "By the Tang era, Chinese printers carved whole pages into wood blocks; the Diamond Sutra of 868 CE is a famous early printed book.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Diamond%20sutra.jpg?width=1024"}, {"name": "The Codex", "rarity": "epic", "id": "the-codex", "subtitle": "Foundational", "details": "Replacing scrolls, the bound codex let readers flip, bookmark and reference pages - the book format still used today.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Codex%20Mendoza%20%28cropped%29.jpg?width=1024"}, {"name": "Locomotive", "rarity": "epic", "id": "locomotive", "subtitle": "Industrial", "details": "Stephenson's Rocket won the 1829 Rainhill Trials and set the pattern for steam locomotives that followed.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Stephenson%27s_Rocket_drawing.jpg?width=1024"}, {"name": "Sewing Machine", "rarity": "epic", "id": "sewing-machine", "subtitle": "Industrial", "details": "Singer popularised the lockstitch sewing machine in the 1850s, though Howe held a key earlier patent.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Sewingmachine1.jpg?width=1024"}, {"name": "Elevator", "rarity": "epic", "id": "elevator", "subtitle": "Industrial", "details": "Elisha Otis's safety brake, shown in 1854, stopped the car if the cable snapped — and made skyscrapers practical.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Spalding_Building%2C_Portland%2C_Oregon_%282012%29_-_15.JPG?width=1024"}, {"name": "Diesel Engine", "rarity": "epic", "id": "diesel-engine", "subtitle": "Industrial", "details": "Rudolf Diesel's 1890s engine ignites fuel by compression alone, squeezing more work from every drop.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Rudolf_Diesel2.jpg?width=1024"}, {"name": "Airship", "rarity": "epic", "id": "airship", "subtitle": "Industrial", "details": "Ferdinand von Zeppelin's rigid airships carried passengers on scheduled flights before aeroplanes could.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/ZR3_USS_Los_Angeles_an_Kriegsschiff.jpg?width=1024"}, {"name": "Typewriter", "rarity": "epic", "id": "typewriter", "subtitle": "Industrial", "details": "The Sholes and Glidden machine of 1868, sold by Remington, gave offices the QWERTY keyboard still in use.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/MEK_II-371.jpg?width=1024"}, {"name": "Anesthesia", "rarity": "epic", "id": "anesthesia", "subtitle": "Medicine", "details": "Ether's public demonstration in 1846 let surgeons operate on sleeping patients instead of struggling ones.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Inside_the_Ether_Dome_at_Massachusetts_General_Hospital.jpg?width=1024"}, {"name": "X-Rays", "rarity": "epic", "id": "x-rays", "subtitle": "Medicine", "details": "Wilhelm Röntgen found rays in 1895 that pass through flesh and photograph the bones within.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Color_X-ray_photogram.jpg?width=1024"}, {"name": "Dishwasher", "rarity": "epic", "id": "dishwasher", "subtitle": "Household", "details": "Josephine Cochrane, tired of servants chipping her china, patented a rack-and-pressure washer in 1886 and founded a company to sell it.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Dishwasher_with_dishes.JPG?width=1024"}, {"name": "Electric Toaster", "rarity": "epic", "id": "electric-toaster", "subtitle": "Household", "details": "Electric toasters appeared around 1905; the pop-up model of the 1920s added a timer and springs so both sides browned without watching.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Toaster.jpg?width=1024"}, {"name": "Hair Dryer", "rarity": "epic", "id": "hair-dryer", "subtitle": "Household", "details": "Alexandre Godefroy's 1890 salon dryer piped hot air from a stove; handheld electric models shrank the idea for home use in the 1920s.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Hairdryer_20101109.jpg?width=1024"}, {"name": "Electric Kettle", "rarity": "epic", "id": "electric-kettle", "subtitle": "Household", "details": "Electric kettles from the 1890s hid a heating element in the base; automatic cut-offs later stopped them boiling dry.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Haden_Vintage_Kettle.jpg?width=1024"}, {"name": "Drip Coffee Maker", "rarity": "epic", "id": "drip-coffee-maker", "subtitle": "Household", "details": "Melitta Bentz's 1908 paper filter started drip brewing; electric machines later automated the hot water, the pause and the warming plate.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Hamilton_Beach_home_coffee_maker.jpg?width=1024"}, {"name": "Blender", "rarity": "epic", "id": "blender", "subtitle": "Household", "details": "Stephen Poplawski put spinning blades at the bottom of a jar in 1922 for soda-fountain drinks; home blenders soon pureed everything.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/HK_Causeway_Bay_Hysan_Place_Eslite_Bookstore_inside_restaurant_kitchen_Electric_blender_Aug-2012.JPG?width=1024"}, {"name": "Rubik's Cube", "rarity": "epic", "id": "rubiks-cube", "subtitle": "Household", "details": "Erno Rubik built his twisting cube in 1974 as a geometry teaching aid, then realised the scrambled puzzle was the point.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Rubiks_cube_solved.jpg?width=1024"}, {"name": "Fiber Optics", "rarity": "epic", "id": "fiber-optics", "subtitle": "Communication", "details": "Kao showed in 1966 that pure glass fibres could carry light signals; Corning made the first low-loss fibre.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Fibreoptic.jpg?width=1024"}, {"name": "GPS", "rarity": "epic", "id": "gps", "subtitle": "Communication", "details": "The US military satellite system went fully operational in 1995; its signals now guide phones and planes.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/GPS_Satellite_NASA_art-iif.jpg?width=1024"}, {"name": "Communications Satellite", "rarity": "epic", "id": "communications-satellite", "subtitle": "Communication", "details": "Telstar 1 relayed the first live transatlantic TV in 1962; Clarke had proposed geostationary relays in 1945.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Telstar.jpg?width=1024"}, {"name": "Barcode", "rarity": "epic", "id": "barcode", "subtitle": "Communication", "details": "Woodland sketched the idea in sand in 1949; a pack of gum became the first barcode-scanned purchase in 1974.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Barcode-scanner.jpg?width=1024"}, {"name": "Microprocessor", "rarity": "epic", "id": "microprocessor", "subtitle": "Computing", "details": "Intel's 4004 of 1971 squeezed a computer's brain onto one chip with 2,300 transistors.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Intel_C4004.jpg?width=1024"}, {"name": "Graphical User Interface", "rarity": "epic", "id": "graphical-user-interface", "subtitle": "Computing", "details": "Xerox PARC's Alto showed windows, icons and a mouse in 1973; the Macintosh took the idea mainstream.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Xerox_Star_8010_ViewPoint.jpg?width=1024"}, {"name": "Computer Mouse", "rarity": "epic", "id": "computer-mouse", "subtitle": "Computing", "details": "Engelbart's team built the first mouse in the 1960s; unveiled in the 1968 'Mother of All Demos', it was patented in 1970.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Douglas_Engelbart%27s_prototype_mouse_-_Computer_History_Museum.jpg?width=1024"}, {"name": "Public-Key Cryptography", "rarity": "epic", "id": "public-key-cryptography", "subtitle": "Computing", "details": "Diffie and Hellman published key exchange in 1976; Rivest, Shamir and Adleman turned it into RSA.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Public_key_encryption.svg?width=1024"}, {"name": "Electronic Spreadsheet", "rarity": "epic", "id": "electronic-spreadsheet", "subtitle": "Computing", "details": "Bricklin and Frankston's VisiCalc of 1979 let one changed number ripple through a whole budget.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/LibreOffice_Calc_6.4.png?width=1024"}, {"name": "Microwave Oven", "rarity": "epic", "id": "microwave-oven", "subtitle": "Accident", "details": "Working by a magnetron in 1945, engineer Percy Spencer found a chocolate bar in his pocket had melted — and tried popcorn next.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/27/Kitchen_island_embedded_microwave.jpg/1280px-Kitchen_island_embedded_microwave.jpg"}, {"name": "Teflon", "rarity": "epic", "id": "teflon", "subtitle": "Accident", "details": "Roy Plunkett opened a refrigerant gas cylinder in 1938 and found it lined with a white, waxy solid: the slipperiest plastic known.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/55/Diamond_surface_nonstick_frying_pan.jpg/1280px-Diamond_surface_nonstick_frying_pan.jpg"}, {"name": "Superglue", "rarity": "epic", "id": "superglue", "subtitle": "Accident", "details": "Cyanoacrylate was rejected in 1942 for sticking to everything it touched — in 1951 its maker realised that was the whole point.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/79/Super_glue.jpg/1280px-Super_glue.jpg"}, {"name": "Chocolate Chip Cookie", "rarity": "epic", "id": "chocolate-chip-cookie", "subtitle": "Accident", "details": "By the standard account, Ruth Wakefield swapped chopped chocolate into cookie dough in 1937, expecting it to melt through. It held.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/1/16/Choc-Chip-Cookie.jpg/1280px-Choc-Chip-Cookie.jpg"}, {"name": "Saccharin", "rarity": "epic", "id": "saccharin", "subtitle": "Accident", "details": "In 1879 Constantin Fahlberg skipped washing his hands after lab work and tasted something intensely sweet at dinner: saccharin.", "image": "https://upload.wikimedia.org/wikipedia/commons/5/57/Sucrin_tabletop_sweetener_packets.jpg"}, {"name": "Bell Rocket Belt", "rarity": "epic", "id": "bell-rocket-belt", "subtitle": "Patent", "details": "Bell's hydrogen-peroxide rocket belt flew beautifully in 1961 demonstrations — for about 21 seconds at a time. The Army lost interest.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Bell%20Rocket%20Belt%20in%20flight.jpg"}, {"name": "Radithor", "rarity": "epic", "id": "radithor", "subtitle": "Patent", "details": "Radithor was radioactive water sold as a cure-all. Industrialist Eben Byers drank it for years; he died of radiation poisoning in 1932.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Radithor%20bottle%20(25799475341).jpg?width=800"}, {"name": "The Mechanical Turk", "rarity": "epic", "id": "mechanical-turk", "subtitle": "Patent", "details": "The 1770 chess-playing 'automaton' toured for decades, beating Franklin and Napoleon. A human operator was hidden inside the cabinet.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Chess%20Automaton%20Willis%201821%2046%20Figure%203.png"}, {"name": "Pulley", "rarity": "rare", "id": "pulley", "subtitle": "Foundational", "details": "Rope-and-wheel pulleys, described in the ancient world, let small crews lift ships, stones and sails far beyond unaided strength.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Manual%20of%20military%20engineering%20%281905%29%20%2814759602516%29.jpg?width=1024"}, {"name": "Archimedes' Screw", "rarity": "rare", "id": "archimedes-screw", "subtitle": "Foundational", "details": "Credited to Archimedes, this rotating spiral tube lifts water uphill and is still used in pumps and modern treatment plants.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Archimedes%20screw%20pump%20at%20Wadebridge%20sewage%20works%20-%20geograph.org.uk%20-%202832347.jpg?width=1024"}, {"name": "Treadwheel Crane", "rarity": "rare", "id": "treadwheel-crane", "subtitle": "Foundational", "details": "Medieval builders walked inside giant treadwheels to hoist cathedral stonework, a human-powered crane used for centuries.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Salisbury%20Cathedral%2C%20tower%20interior%2C%20treadmill%20crane.jpg?width=1024"}, {"name": "Watermill", "rarity": "rare", "id": "watermill", "subtitle": "Foundational", "details": "Waterwheels ground grain, sawed timber and drove forge hammers, harnessing rivers as industry's first widespread power source.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Caythorpe%20Mill%20waterwheel%20-%20geograph.org.uk%20-%201551421.jpg?width=1024"}, {"name": "Windmill", "rarity": "rare", "id": "windmill", "subtitle": "Foundational", "details": "Persian windmills ground grain by the early medieval era; European tower mills later pumped water and powered mills of every kind.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Amrumer%20Windm%C3%BChle%20%282018%29.jpg?width=1024"}, {"name": "Abacus", "rarity": "rare", "id": "abacus", "subtitle": "Foundational", "details": "Counting boards and bead frames from Mesopotamia to China let merchants calculate quickly centuries before mechanical calculators.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Chinese%20Suanpan%20Abacus.jpg?width=1024"}, {"name": "Eyeglasses", "rarity": "rare", "id": "eyeglasses", "subtitle": "Foundational", "details": "Wearable eyeglasses appeared in Italy by the late 1200s, extending reading life for scholars, scribes and craftspeople.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Catalogue%20of%20the%20historical%20collection%20of%20miniatures%20formed%20by%20Mr.%20J.%20Lumsden%20Propert%20and%20exhibited%20at%20the%20Fine%20Art%20Society%27s%20%281897%29%20%2814578149458%29.jpg?width=640"}, {"name": "Bi Sheng's Movable Type", "rarity": "rare", "id": "bi-shengs-movable-type", "subtitle": "Foundational", "details": "In 1040s China, Bi Sheng carved individual characters in baked clay - the earliest known movable type, centuries before Gutenberg.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ningxia%20Museum%20wooden%20moveable%20print%20frame.jpg?width=1024"}, {"name": "Stirrup", "rarity": "rare", "id": "stirrup", "subtitle": "Foundational", "details": "Paired riding stirrups, developed in Asia and spread by the early medieval era, gave mounted riders stability that reshaped warfare.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Horses%20are%20used%20for%20work%20and%20recreational%20riding%20at%20the%20Birdwell%20Clark%20Ranch.%20%2824815544960%29.jpg?width=1024"}, {"name": "Crossbow", "rarity": "rare", "id": "crossbow", "subtitle": "Foundational", "details": "Used in China by the 7th century BCE, the crossbow stored energy in a drawn prod and let less-trained soldiers loose powerful bolts.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Hunting%20crossbow%20of%20about%201590%2C%20V%26A%20London.jpg?width=1024"}, {"name": "Greek Fire", "rarity": "rare", "id": "greek-fire", "subtitle": "Foundational", "details": "A Byzantine incendiary sprayed from shipboard siphons, Greek fire burned on water; its exact formula remains unknown today.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Greekfire-madridskylitzes1.jpg?width=1024"}, {"name": "Porcelain", "rarity": "rare", "id": "porcelain", "subtitle": "Foundational", "details": "Chinese kilns perfected true porcelain by the Tang and Song eras - white, translucent ware prized and imitated worldwide.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ming%20Porcelain%20Vase%2001.jpg?width=1024"}, {"name": "Spinning Jenny", "rarity": "rare", "id": "spinning-jenny", "subtitle": "Industrial", "details": "James Hargreaves' 1764 frame spun many threads at once, multiplying a spinner's output by eight or more.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Spinning_jenny.jpg?width=1024"}, {"name": "Cotton Gin", "rarity": "rare", "id": "cotton-gin", "subtitle": "Industrial", "details": "Eli Whitney's 1794 gin pulled seeds from cotton fibre with wire teeth, fifty times faster than by hand.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Cotton_gin_EWM_2007.jpg?width=1024"}, {"name": "Bessemer Process", "rarity": "rare", "id": "bessemer-process", "subtitle": "Industrial", "details": "Henry Bessemer's 1856 converter blasted air through molten iron, making steel cheap enough to build with.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Bessemer_converter.jpg?width=1024"}, {"name": "Dynamite", "rarity": "rare", "id": "dynamite", "subtitle": "Industrial", "details": "Alfred Nobel tamed nitroglycerin in 1867 by soaking it into kieselguhr, making a safe, portable explosive.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Inserting_dynamite_into_hole.jpg?width=1024"}, {"name": "Bicycle", "rarity": "rare", "id": "bicycle", "subtitle": "Industrial", "details": "The 1885 safety bicycle — equal wheels, chain drive, rear wheel driven — is the design still ridden today.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Rover_safety_bicycle_of_1885_%28right%29.jpg?width=1024"}, {"name": "Voltaic Pile", "rarity": "rare", "id": "voltaic-pile", "subtitle": "Industrial", "details": "Alessandro Volta's 1800 stack of zinc and copper discs was the first battery, giving a steady electric current.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Voltaic_pile_battery.png?width=1024"}, {"name": "Pneumatic Tire", "rarity": "rare", "id": "pneumatic-tire", "subtitle": "Industrial", "details": "John Boyd Dunlop's 1888 air-filled tyre, made for his son's tricycle, smoothed the ride for bikes and cars.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Large_tyre.jpg?width=1024"}, {"name": "Hot Air Balloon", "rarity": "rare", "id": "hot-air-balloon", "subtitle": "Industrial", "details": "The Montgolfier brothers' balloon carried the first people aloft in 1783, over the rooftops of Paris.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2006_Ojiya_balloon_festival_011.jpg?width=1024"}, {"name": "Assembly Line", "rarity": "rare", "id": "assembly-line", "subtitle": "Industrial", "details": "Ford's moving line of 1913 brought the work to the worker, cutting Model T chassis assembly from hours to 93 minutes.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/A321_final_assembly_%289351765668%29.jpg?width=1024"}, {"name": "Stethoscope", "rarity": "rare", "id": "stethoscope", "subtitle": "Medicine", "details": "René Laennec rolled a paper tube in 1816 to hear a patient's chest — the first stethoscope was wooden and single-eared.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Stethoscope-2.png?width=1024"}, {"name": "Insulin", "rarity": "rare", "id": "insulin", "subtitle": "Medicine", "details": "Isolated in Toronto in 1921 by Banting, Best and colleagues, insulin turned type 1 diabetes from fatal to manageable.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Inzul%C3%ADn.jpg?width=1024"}, {"name": "Microscope", "rarity": "rare", "id": "microscope", "subtitle": "Medicine", "details": "Compound microscopes appeared around 1600, credited to the Janssens; Leeuwenhoek's single lens revealed microbes.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ukrainian_microscope_%28cropped%29.jpg?width=1024"}, {"name": "Zipper", "rarity": "rare", "id": "zipper", "subtitle": "Household", "details": "Whitcomb Judson's 1893 clasp locker was clumsy; Gideon Sundback's 1913 interlocking teeth made the fast, reliable zip we know.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Coil_plastic_and_metal_zippers.jpg?width=1024"}, {"name": "Safety Razor", "rarity": "rare", "id": "safety-razor", "subtitle": "Household", "details": "King Camp Gillette's 1901 razor paired a guarded handle with cheap disposable blades, ending daily strop-and-hone shaving.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Parker-76R_Safety_Razor.jpg?width=1024"}, {"name": "Ballpoint Pen", "rarity": "rare", "id": "ballpoint-pen", "subtitle": "Household", "details": "Laszlo Biro, frustrated by fountain pens, patented a tiny rolling ball fed by quick-drying ink in 1938; pilots loved its leak-free flow.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/03-BICcristal2008-03-26.jpg?width=1024"}, {"name": "Fountain Pen", "rarity": "rare", "id": "fountain-pen", "subtitle": "Household", "details": "Lewis Waterman's 1884 capillary feed channelled ink to the nib in a steady flow, taming the blots of earlier reservoir pens.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Fountain_pen_writing_%28literacy%29.jpg?width=1024"}, {"name": "Paperclip", "rarity": "rare", "id": "paperclip", "subtitle": "Household", "details": "The Gem paperclip's double loop of wire appeared around 1899; earlier and later patents chased the same job with different bends.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Wanzijia.jpg?width=1024"}, {"name": "Stapler", "rarity": "rare", "id": "stapler", "subtitle": "Household", "details": "Desktop staplers took decades to agree on loading and form; the familiar top-loading swing design settled in the 1930s and 1940s.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2017_Zszywacz_biurowy.jpg?width=1024"}, {"name": "Adhesive Tape", "rarity": "rare", "id": "adhesive-tape", "subtitle": "Household", "details": "Richard Drew invented masking tape in 1925 for car painters, then clear cellulose tape in 1930 for sealing, mending and wrapping.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Scotch_tape.jpg?width=1024"}, {"name": "Crayons", "rarity": "rare", "id": "crayons", "subtitle": "Household", "details": "Binney and Smith's 1903 box of eight wax crayons cost a nickel and put safe, cheap colour in every child's hand; the dustless chalk came first.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Six_Colored_Crayons%2C_Full_Size%2C_One_Cent%2C_1896.jpg?width=1024"}, {"name": "Jigsaw Puzzle", "rarity": "rare", "id": "jigsaw-puzzle", "subtitle": "Household", "details": "John Spilsbury pasted a map on wood and cut out the countries around 1760, inventing a geography lesson that became a pastime.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Jigsaw_puzzle_01_by_Scouten.jpg?width=1024"}, {"name": "Teddy Bear", "rarity": "rare", "id": "teddy-bear", "subtitle": "Household", "details": "In 1902 a cartoon of Theodore Roosevelt sparing a bear cub inspired toy makers in America and Germany to sell soft bears in his name.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Teddy_bear_produced_in_1903_face_detail%2C_from-_Teddy_bear_early_1900s_-_Smithsonian_Museum_of_Natural_History_%28cropped%29.jpg?width=1024"}, {"name": "Velcro", "rarity": "rare", "id": "velcro", "subtitle": "Household", "details": "George de Mestral studied burdock burrs clinging to his dog in 1941 and copied their hooks with nylon loops; he patented the fastener in 1955.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Velcro_Hooks.jpg?width=1024"}, {"name": "Smoke Detector", "rarity": "rare", "id": "smoke-detector", "subtitle": "Household", "details": "Home smoke alarms of the late 1960s put ionisation sensors on ceilings; a cheap battery box turned a laboratory idea into a lifesaver.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Smoke_detector.JPG?width=1024"}, {"name": "Clothes Dryer", "rarity": "rare", "id": "clothes-dryer", "subtitle": "Household", "details": "Early hand-cranked dryers ventilated clothes over heat; electric tumble dryers of the 1930s and 1940s made the rainy-day wash routine simple.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Whirlpool_Cabrio_Dryer.jpg?width=1024"}, {"name": "Telegraph", "rarity": "rare", "id": "telegraph", "subtitle": "Communication", "details": "Cooke, Wheatstone and Morse raced rival electric telegraphs in 1837; Morse's line linked Washington in 1844.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Morse_telegraph.jpg?width=1024"}, {"name": "Phonograph", "rarity": "rare", "id": "phonograph", "subtitle": "Communication", "details": "Edison's 1877 tinfoil phonograph was the first machine to record and play back a human voice.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/EdisonPhonograph.jpg?width=1024"}, {"name": "Braille", "rarity": "rare", "id": "braille", "subtitle": "Communication", "details": "Blind teenager Louis Braille published his raised-dot reading system in 1829, adapting a military night code.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Reading_Braille.jpg?width=1024"}, {"name": "Email", "rarity": "rare", "id": "email", "subtitle": "Communication", "details": "Ray Tomlinson sent the first networked email in 1971 and chose the @ sign to separate user from machine.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Evolution_36_mail.png?width=1024"}, {"name": "Carbon Microphone", "rarity": "rare", "id": "carbon-microphone", "subtitle": "Communication", "details": "Hughes demonstrated a carbon microphone in 1878; Edison and Berliner held rival patents — it made the telephone practical.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Hughes%20carbon%20rod%20microphone%201878.png?width=1024"}, {"name": "Fax Machine", "rarity": "rare", "id": "fax-machine", "subtitle": "Communication", "details": "Bain patented an image-scanning chemical telegraph in 1843 — decades before the telephone it would one day ride on.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Muirhead%20fax%20machine%20-%20MfK%20Bern.jpg?width=1024"}, {"name": "Touchscreen", "rarity": "rare", "id": "touchscreen", "subtitle": "Computing", "details": "E.A. Johnson described a capacitive touchscreen in 1965; multi-touch later put it in every pocket.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Hear_Music_touchscreen.jpg?width=1024"}, {"name": "Vacuum Tube", "rarity": "rare", "id": "vacuum-tube", "subtitle": "Computing", "details": "Fleming's valve of 1904 and De Forest's Audion amplified signals and powered early radio and computers.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/De_Forest_Audion_AM_radio_transmitters.jpg?width=1024"}, {"name": "Punch-Card Computing", "rarity": "rare", "id": "punch-card-computing", "subtitle": "Computing", "details": "Hollerith's punched cards tallied the 1890 US census in record time; his firm became part of IBM.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8f/Card_puncher_-_NARA_-_513295.jpg/1280px-Card_puncher_-_NARA_-_513295.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"}, {"name": "Universal Machine", "rarity": "rare", "id": "universal-machine", "subtitle": "Computing", "details": "Turing's 1936 paper described a machine that could simulate any other - the blueprint of all computers.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Machine_de_Turing_p%C3%A9dagogique.jpg?width=1024"}, {"name": "Compiler", "rarity": "rare", "id": "compiler", "subtitle": "Computing", "details": "Grace Hopper built the first compiler in 1952, translating human-written code into machine instructions.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Grace_Hopper_and_UNIVAC.jpg?width=1024"}, {"name": "Magnetic Disk Storage", "rarity": "rare", "id": "magnetic-disk-storage", "subtitle": "Computing", "details": "IBM's RAMAC of 1956 stored data on fifty spinning disks - five megabytes in a cabinet-sized drive.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/IBM_Almaden_%28145378554%29.jpg?width=1024"}, {"name": "Popsicle", "rarity": "rare", "id": "popsicle", "subtitle": "Accident", "details": "In 1905 Frank Epperson left a stirred soda outside on a cold night; by morning it was frozen solid around its stirring stick.", "image": "https://upload.wikimedia.org/wikipedia/commons/a/a7/Ice_Lolly.jpg"}, {"name": "Corn Flakes", "rarity": "rare", "id": "corn-flakes", "subtitle": "Accident", "details": "The Kellogg brothers left boiled wheat sitting out in 1894; rolling the stale dough anyway produced thin, crisp flakes.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/37/Corn_flakes_in_a_bowl.jpg/1280px-Corn_flakes_in_a_bowl.jpg"}, {"name": "Silly Putty", "rarity": "rare", "id": "silly-putty", "subtitle": "Accident", "details": "A wartime search for synthetic rubber produced a goo that stretched, bounced and lifted newsprint — useless for war, perfect as a toy.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f3/Silly_putty_dripping.jpg/1280px-Silly_putty_dripping.jpg"}, {"name": "Slinky", "rarity": "rare", "id": "slinky", "subtitle": "Accident", "details": "In 1943 naval engineer Richard James knocked a torsion spring off a shelf and watched it walk, end over end, across the floor.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f3/2006-02-04_Metal_spiral.jpg/1280px-2006-02-04_Metal_spiral.jpg"}, {"name": "Vulcanized Rubber", "rarity": "rare", "id": "vulcanized-rubber", "subtitle": "Accident", "details": "By the usual account, Goodyear spilled rubber and sulfur on a hot stove in 1839; instead of melting, it cured tough and springy.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/All%20Season%20tire%20tread%20and%20code.JPG?width=1024"}, {"name": "Bubble Wrap", "rarity": "rare", "id": "bubble-wrap", "subtitle": "Accident", "details": "Fielding and Chavannes sealed two shower curtains together in 1957 as textured wallpaper; the air-pocket sheet failed as decor, won as packing.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6b/Bubble_Wrap.jpg/1280px-Bubble_Wrap.jpg"}, {"name": "Mauve Dye", "rarity": "rare", "id": "mauve-dye", "subtitle": "Accident", "details": "Teenager William Perkin was trying to synthesise quinine in 1856 when his flask yielded a vivid purple: the first synthetic dye.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Claude%20Bornet%2C%20An%20Elderly%20Lady%20in%20a%20Mauve%20Silk%20Dress%2C%201767%2C%20NGA%20112852.jpg?width=1024"}, {"name": "Coca-Cola", "rarity": "rare", "id": "coca-cola", "subtitle": "Accident", "details": "Atlanta pharmacist John Pemberton brewed his 1886 tonic as a patent medicine; its soda-fountain afterlife was the real invention.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ef/Coca-Cola_glass_bottle.jpg/1280px-Coca-Cola_glass_bottle.jpg"}, {"name": "Ice Cream Cone", "rarity": "rare", "id": "ice-cream-cone", "subtitle": "Accident", "details": "By the famous fair tale, a waffle seller rolled a cone for a dishless ice-cream man in 1904 — but a cone mould was patented in 1903.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/0/00/Dark_chocolate_chip_ice_cream_cone_-_August_2025_-_Sarah_Stierch.jpg/1280px-Dark_chocolate_chip_ice_cream_cone_-_August_2025_-_Sarah_Stierch.jpg"}, {"name": "Tesla's Death Ray", "rarity": "rare", "id": "teslas-death-ray", "subtitle": "Patent", "details": "In the 1930s Tesla pitched 'Teleforce,' a particle-beam weapon he said could end war. It was never built, and no funder bought it.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Nikola%20Tesla%2C%20with%20his%20equipment%20EDIT.jpg?width=1024"}, {"name": "Cold Fusion", "rarity": "rare", "id": "cold-fusion", "subtitle": "Patent", "details": "In 1989 Pons and Fleischmann announced fusion in a jar of heavy water. Other labs could not replicate it, and the claim collapsed.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Fleischmann%20Pons%20schema%20reattore%2001it.jpg?width=1024"}, {"name": "The Parachute Suit", "rarity": "rare", "id": "parachute-suit", "subtitle": "Patent", "details": "Tailor Franz Reichelt tested his wearable parachute from the Eiffel Tower in 1912, before cameras. It failed, and he did not survive.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Franz%20Reichelt%20(high%20res).jpg?width=1024"}, {"name": "Heroin Cough Syrup", "rarity": "rare", "id": "heroin-cough-syrup", "subtitle": "Patent", "details": "Bayer launched heroin in 1898 as a cough remedy and sold it for use by children. It was later recognized as highly addictive.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Bayer%20Heroin%20bottle.jpg?width=1024"}, {"name": "The Baby Cage", "rarity": "rare", "id": "baby-cage", "subtitle": "Patent", "details": "Emma Read's 1923 patent (US 1,448,235) hung a wire cage outside apartment windows so babies could get fresh air, stories above the street.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/US1448235%20Portable%20Baby%20Cage%20Fig%201.png?width=1024"}, {"name": "The Safety Coffin", "rarity": "rare", "id": "safety-coffin", "subtitle": "Patent", "details": "Fear of being buried alive filled the 1800s with coffins fitted with bells, flags, ladders and breathing tubes for the not-quite-dead.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Safetycoffin.jpg"}, {"name": "Tesla's Earthquake Machine", "rarity": "rare", "id": "teslas-earthquake-machine", "subtitle": "Patent", "details": "Tesla claimed his pocket-sized 1898 oscillator shook his New York lab and nearly the building. No independent test ever confirmed it.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/TeslaOscillator.png"}, {"name": "Square-Wheeled Tricycle", "rarity": "rare", "id": "square-wheeled-tricycle", "subtitle": "Patent", "details": "Patented in 2016 (US 9,472,120), this tricycle's square wheels roll smoothly — but only on a road of precisely shaped catenary bumps.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Museum%20of%20Mathematics-New%20York-Square%20Wheeled%20Tricycles.jpg?width=1024"}, {"name": "Sundial", "rarity": "uncommon", "id": "sundial", "subtitle": "Foundational", "details": "From Egyptian shadow clocks to Greek dials, sundials divided daylight by the sun's moving shadow for over three thousand years.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Warszawskie%20pionowe%20zegary%20s%C5%82oneczne%20Grzybowska%202.jpg?width=1024"}, {"name": "Water Clock", "rarity": "uncommon", "id": "water-clock", "subtitle": "Foundational", "details": "Clepsydras measured time by flowing water, working indoors and at night when sundials could not - used in Egypt, Greece and China.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Bulletin%20-%20United%20States%20National%20Museum%20%281959%29%20%2820481431946%29.jpg?width=1024"}, {"name": "The Loom", "rarity": "uncommon", "id": "the-loom", "subtitle": "Foundational", "details": "Looms interlacing warp and weft date back over 6,000 years; treadle and frame looms sped weaving in workshops worldwide.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Tais%20weaving%20Loom%20-%20Com.jpg?width=1024"}, {"name": "Soap", "rarity": "uncommon", "id": "soap", "subtitle": "Foundational", "details": "Soap-like mixtures appear in Babylonian records; hard soap from plant ash and fats became a staple of washing and hygiene.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Aleppo%20Soap%209195.jpg?width=1024"}, {"name": "Kite", "rarity": "uncommon", "id": "kite", "subtitle": "Foundational", "details": "Kites flew in China over 2,000 years ago for signalling and measuring distances before spreading worldwide as tools and toys.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Flying%20Kite.jpg?width=1024"}, {"name": "Seismoscope", "rarity": "uncommon", "id": "seismoscope", "subtitle": "Foundational", "details": "Zhang Heng's seismoscope of 132 CE used a swinging pendulum and bronze balls to signal the direction of distant earthquakes.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Valladolid%20-%20Museo%20Oriental%20de%20Valladolid%2009.jpg?width=1024"}, {"name": "South-Pointing Chariot", "rarity": "uncommon", "id": "south-pointing-chariot", "subtitle": "Foundational", "details": "Chinese engineers built chariots whose figure always pointed south using geared wheels - a mechanical compass without magnets.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/South-pointing%20chariot%20in%20the%20National%20Museum%20of%20Natural%20Science%2020241024.jpg?width=1024"}, {"name": "Wheelbarrow", "rarity": "uncommon", "id": "wheelbarrow", "subtitle": "Foundational", "details": "The single-wheeled barrow, used in China by the Han era, put the wheel under the load so one person could haul heavy goods.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/China-wheelbarrows-Beijing-1230830.jpg?width=1024"}, {"name": "Paper Money", "rarity": "uncommon", "id": "paper-money", "subtitle": "Foundational", "details": "Song-dynasty China issued state paper notes in the 11th century, centuries before banknotes became routine in Europe.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Jiao%20zi.jpg?width=1024"}, {"name": "Pottery Wheel", "rarity": "uncommon", "id": "pottery-wheel", "subtitle": "Foundational", "details": "Fast potter's wheels in Mesopotamia by c. 3500 BCE let throwers shape even, thin-walled vessels quickly and repeatably.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Japanese%20wheel%20pottery%20workshop.jpg?width=1024"}, {"name": "Distilled Spirits", "rarity": "uncommon", "id": "distilled-spirits", "subtitle": "Foundational", "details": "Medieval distillers in the Islamic world and Europe refined distillation, concentrating alcohol for medicines and spirits.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/An%20Alchemist%20in%20His%20Studio%20-%20DPLA%20-%206d56eba7861bee9e66825fc5590aa1b3.jpg?width=1024"}, {"name": "Catapult", "rarity": "uncommon", "id": "catapult", "subtitle": "Foundational", "details": "Torsion engines like the catapult, developed in the Greek world by 400 BCE, hurled stones to crack walls no ram could reach.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Reconstructed%20ballistra%20at%20Gamla.jpg?width=1024"}, {"name": "Horseshoe", "rarity": "uncommon", "id": "horseshoe", "subtitle": "Foundational", "details": "Nailed iron horseshoes, widespread by the early medieval era, protected hooves on hard roads and extended horses' working lives.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Mule%20in%20stocks%20waiting%20to%20be%20shod%20%284688592858%29.jpg?width=1024"}, {"name": "Bellows", "rarity": "uncommon", "id": "bellows", "subtitle": "Foundational", "details": "Hand and foot bellows forced air into furnaces, letting smiths reach temperatures that smelted and worked iron and bronze.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Blacksmith%20J1.jpg?width=640"}, {"name": "Shaduf", "rarity": "uncommon", "id": "shaduf", "subtitle": "Foundational", "details": "The shaduf, a counterweighted sweep used in Egypt and Mesopotamia, lifted river water into irrigation channels bucket by bucket.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Shad%C3%BBf.%20The%20weight%20of%20the%20water%20in%20the%20bucket%20is%20balanced%20by%20the%20lump%20of%20Nile%20mud%20at%20the%20other%20end%20of%20the%20swinging%20beam%2C%20and%20the%20water%20is%20thus%20raised%20to%20the%20mouth%20of%20the%20canal%20with%20little%20%28NYPL%20b10607452-80835%29.jpg?width=1024"}, {"name": "Fire Lance", "rarity": "uncommon", "id": "fire-lance", "subtitle": "Foundational", "details": "The Chinese fire lance of the 10th-12th centuries packed gunpowder in a bamboo tube - an ancestor of firearms and rockets.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Chinese%20Hand%20Cannon%20with%20Pellets.jpg?width=1024"}, {"name": "Playing Cards", "rarity": "uncommon", "id": "playing-cards", "subtitle": "Foundational", "details": "Cards reached China by the Tang era and Europe by the 1370s, evolving from money-like designs into the suits used today.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Mamluk%20playing%20card%201.jpg?width=1024"}, {"name": "Power Loom", "rarity": "uncommon", "id": "power-loom", "subtitle": "Industrial", "details": "Edmund Cartwright's 1785 steam-driven loom moved weaving from cottages into the great textile mills.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Roberts_loom-marsden_front.png?width=1024"}, {"name": "Flying Shuttle", "rarity": "uncommon", "id": "flying-shuttle", "subtitle": "Industrial", "details": "John Kay's 1733 shuttle flew across the loom on wheels, letting one weaver do the work of two.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Haslach_an_der_M%C3%BChl_-_Textiles_Zentrum_Haslach_-_21_-_Weberschiffchen.jpg?width=1024"}, {"name": "Seed Drill", "rarity": "uncommon", "id": "seed-drill", "subtitle": "Industrial", "details": "Jethro Tull's 1701 drill planted seeds in neat, evenly spaced rows instead of scattering them by hand.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/7263_Canterbury_Agricultural_College_farm.jpg?width=1024"}, {"name": "Mechanical Reaper", "rarity": "uncommon", "id": "mechanical-reaper", "subtitle": "Industrial", "details": "Cyrus McCormick's reaper, demonstrated in 1831, cut grain as fast as several men with scythes.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Fahr-Getreidem%C3%A4hmaschine_2.jpg?width=1024"}, {"name": "Threshing Machine", "rarity": "uncommon", "id": "threshing-machine", "subtitle": "Industrial", "details": "Andrew Meikle's 1780s machine beat grain from the straw mechanically, ending centuries of flail work.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Threshing_Machine_In_Action.jpg?width=1024"}, {"name": "Electric Motor", "rarity": "uncommon", "id": "electric-motor", "subtitle": "Industrial", "details": "Early motors of the 1830s turned electricity into rotation; Faraday's experiments laid their foundations.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/VEM_motor_Wernigerode.png?width=320"}, {"name": "AC Transformer", "rarity": "uncommon", "id": "ac-transformer", "subtitle": "Industrial", "details": "The transformer steps AC voltage up for long journeys and down for safe use, making power grids possible.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Polemount-singlephase-closeup.jpg?width=1024"}, {"name": "Tractor", "rarity": "uncommon", "id": "tractor", "subtitle": "Industrial", "details": "Steam traction engines came first; gasoline tractors of the early 1900s took the ploughing to the engine.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ford_8N.jpg?width=1024"}, {"name": "Submarine", "rarity": "uncommon", "id": "submarine", "subtitle": "Industrial", "details": "Cornelis Drebbel rowed a leather-covered submersible under the Thames in the 1620s; Bushnell's Turtle followed in 1776.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Turtle_model_at_the_Royal_navy_submarine_museum.jpg?width=1024"}, {"name": "Parachute", "rarity": "uncommon", "id": "parachute", "subtitle": "Industrial", "details": "André-Jacques Garnerin made the first parachute descent from a balloon in 1797, swinging under a silk canopy.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Bangladesh_Air_Force_%28BAF%29_paratroopers_jump_from_a_U.S._Air_Force_C-130_Hercules_aircraft_over_Bangladesh_during_exercise_Cope_South_14_Nov._10%2C_2013_131110-F-SI013-240.jpg?width=1024"}, {"name": "Bakelite", "rarity": "uncommon", "id": "bakelite", "subtitle": "Industrial", "details": "Leo Baekeland's 1907 Bakelite was the first fully synthetic plastic, moulded into phones, radios and handles.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Bakelittelefon_1947a.jpg?width=1024"}, {"name": "Stainless Steel", "rarity": "uncommon", "id": "stainless-steel", "subtitle": "Industrial", "details": "Harry Brearley added chromium to steel in 1913 while seeking gun barrels — and found it would not rust.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Cutlery_designed_by_Zaha_Hadid_for_company_WMF%2C_2007_N.4.jpg?width=1024"}, {"name": "Barbed Wire", "rarity": "uncommon", "id": "barbed-wire", "subtitle": "Industrial", "details": "Joseph Glidden's 1874 barbed wire fenced the open range cheaply, remaking farming across the plains.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Rusted_barbed_wire.jpg?width=1024"}, {"name": "Pasteurization", "rarity": "uncommon", "id": "pasteurization", "subtitle": "Medicine", "details": "Louis Pasteur showed gentle heating in the 1860s stops wine and milk souring by killing microbes.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Louis_Pasteur%2C_foto_av_Paul_Nadar%2C_Crisco_edit.jpg?width=1024"}, {"name": "Antiseptic Surgery", "rarity": "uncommon", "id": "antiseptic-surgery", "subtitle": "Medicine", "details": "Joseph Lister's carbolic spray and dressings of the 1860s cut surgical infections dramatically.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Joseph_Lister_1902.jpg?width=1024"}, {"name": "Blood Transfusion", "rarity": "uncommon", "id": "blood-transfusion", "subtitle": "Medicine", "details": "Early transfusions often killed; Landsteiner's 1901 blood groups explained why, and made the practice safe.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Erythrozytenkonzentrat_neu.jpg?width=1024"}, {"name": "Hypodermic Syringe", "rarity": "uncommon", "id": "hypodermic-syringe", "subtitle": "Medicine", "details": "Hollow needles and syringes of the 1850s, by Pravaz and Wood separately, put medicine under the skin precisely.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Syringe2.jpg?width=1024"}, {"name": "Aspirin", "rarity": "uncommon", "id": "aspirin", "subtitle": "Medicine", "details": "Bayer chemist Felix Hoffmann synthesised a pure, stable aspirin in 1897, from a remedy in willow bark.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Acetylsalicylic_acid.jpg?width=1024"}, {"name": "Contact Lenses", "rarity": "uncommon", "id": "contact-lenses", "subtitle": "Medicine", "details": "First worn in the 1880s as blown-glass shells; plastic lenses of the 1930s made them bearable for hours.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Contactlenzen_Confortissimo.JPG?width=1024"}, {"name": "Rubber Band", "rarity": "uncommon", "id": "rubber-band", "subtitle": "Household", "details": "Stephen Perry patented the elastic rubber band in 1845, slicing vulcanised rubber tubes into loops that grip letters, jars and bundles.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Rubber_bands.jpg?width=1024"}, {"name": "Glue Stick", "rarity": "uncommon", "id": "glue-stick", "subtitle": "Household", "details": "Henkel's 1969 Pritt stick borrowed the lipstick tube's twist-up design, spreading solid adhesive cleanly without drips or sticky fingers.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Pritt_Sticks.JPG?width=1024"}, {"name": "Highlighter", "rarity": "uncommon", "id": "highlighter", "subtitle": "Household", "details": "Felt-tip highlighters of the early 1960s laid transparent fluorescent ink over text, marking the important lines while keeping them readable.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Highlighter_pen_-photocopied_text-9Mar2009.jpg?width=1024"}, {"name": "Interlocking Toy Brick", "rarity": "uncommon", "id": "interlocking-toy-brick", "subtitle": "Household", "details": "Ole Kirk Christiansen's company perfected studs-and-tubes bricks in 1958; the clutch power let builds hold together and pull apart cleanly.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lego_bricks.jpg?width=1024"}, {"name": "Nonstick Pan", "rarity": "uncommon", "id": "nonstick-pan", "subtitle": "Household", "details": "Roy Plunkett's accidental 1938 discovery of PTFE became a pan coating in the 1950s; eggs have been sliding out ever since.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Blintzes_in_frying_pan.jpg?width=1024"}, {"name": "Tupperware", "rarity": "uncommon", "id": "tupperware", "subtitle": "Household", "details": "Earl Tupper's 1946 polyethylene tubs sealed with a paint-can-style burping lid, keeping leftovers fresher far longer than a plate on top.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/1960s_Norwegian_Panco_Plast_Fredrikstad_plastic_kitchen_storage_container_number_192_for_dry_goods_view_3.jpg?width=1024"}, {"name": "Aluminum Foil", "rarity": "uncommon", "id": "aluminum-foil", "subtitle": "Household", "details": "Rolled aluminium foil replaced tin foil commercially around 1910: lighter, rust-free and happy to wrap sandwiches or line a grill.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Aluminio.jpg?width=1024"}, {"name": "Plastic Wrap", "rarity": "uncommon", "id": "plastic-wrap", "subtitle": "Household", "details": "Ralph Wiley stumbled on PVDC film in 1933 while washing laboratory glassware; cling film reached kitchens after the Second World War.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Pvc-Film.jpg?width=1024"}, {"name": "Can Opener", "rarity": "uncommon", "id": "can-opener", "subtitle": "Household", "details": "Cans existed for decades before openers did; Ezra Warner's 1858 design was so awkward that shops kept one to open tins for customers.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Kitchen-Modern-Can-Opener.jpg?width=1024"}, {"name": "Corkscrew", "rarity": "uncommon", "id": "corkscrew", "subtitle": "Household", "details": "Corkscrews borrowed the worm from gun-cleaning tools in the 1600s; hundreds of patents since have levered, winged and twisted the cork out.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Corkscrews_December_2014-1.jpg?width=1024"}, {"name": "Clothes Hanger", "rarity": "uncommon", "id": "clothes-hanger", "subtitle": "Household", "details": "Wire hangers inspired by coat hooks appeared in the 1860s; Albert Parkhouse's 1903 twisted-wire version was devised for coatless factory pegs.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Wire-and-Wooden-CoatHangers.JPG?width=1024"}, {"name": "Electric Iron", "rarity": "uncommon", "id": "electric-iron", "subtitle": "Household", "details": "Henry Seeley's 1882 electric iron weighed nearly 15 pounds and heated on a stand; thermostats later made pressing far less perilous.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Teal_and_white_electric_steam_iron_-_side_view.jpg?width=1024"}, {"name": "Light Switch", "rarity": "uncommon", "id": "light-switch", "subtitle": "Household", "details": "John Henry Holmes's 1884 quick-break switch snapped contacts apart fast enough to stop arcing, making wall switches safe and durable.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Rocker_light_switch.jpg?width=1024"}, {"name": "Doorbell", "rarity": "uncommon", "id": "doorbell", "subtitle": "Household", "details": "Electric bells using vibrating contacts were described by Joseph Henry in 1831; the buzzing button replaced servants' bells and loud knocking.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Bell_button_beside_an_entrance_door_in_Venice%2C_Italy.jpg?width=1024"}, {"name": "Fire Extinguisher", "rarity": "uncommon", "id": "fire-extinguisher", "subtitle": "Household", "details": "Ambrose Godfrey's 1723 extinguisher used a small charge to scatter water; portable soda-acid and later dry-powder types shrank it for the home.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Wheeled_fire_extinguisher.jpg?width=1024"}, {"name": "Flashlight", "rarity": "uncommon", "id": "flashlight", "subtitle": "Household", "details": "David Misell's 1899 patent put dry-cell batteries and a bulb in a paper tube: a portable light you could finally switch on in one hand.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/LED_Flashlights.jpg?width=1024"}, {"name": "Lawn Mower", "rarity": "uncommon", "id": "lawn-mower", "subtitle": "Household", "details": "Edwin Budding's 1830 cylinder mower, adapted from cloth-trimming machinery, let sports grounds and gardeners cut grass evenly without a scythe.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lawn_Mowing_DVIDS119604.jpg?width=1024"}, {"name": "Shopping Cart", "rarity": "uncommon", "id": "shopping-cart", "subtitle": "Household", "details": "Sylvan Goldman added wheels and two baskets to a folding chair in 1937; shoppers only adopted his cart after hired models pushed them around.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Frau_mit_Einkaufswagen_%2837939692236%29.jpg?width=1024"}, {"name": "Toothbrush", "rarity": "uncommon", "id": "toothbrush", "subtitle": "Household", "details": "William Addis mass-produced bone-handled bristle brushes in 1780, an idea he had carved in prison; nylon bristles modernised it in 1938.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Toothbrush_20050716_004.jpg?width=1024"}, {"name": "Dental Floss", "rarity": "uncommon", "id": "dental-floss", "subtitle": "Household", "details": "Levi Spear Parmly promoted silk thread between teeth in 1819; waxed floss was patented in 1898 and nylon floss followed in the 1940s.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Floss4.jpg?width=1024"}, {"name": "Toilet Paper", "rarity": "uncommon", "id": "toilet-paper", "subtitle": "Household", "details": "Joseph Gayetty sold medicated paper in 1857; the perforated roll on a tube, patented in 1891, is the form bathrooms settled on.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Toiletpapier_%28Gobran111%29.jpg?width=1024"}, {"name": "Water Heater", "rarity": "uncommon", "id": "water-heater", "subtitle": "Household", "details": "Edwin Ruud's 1889 automatic storage heater gave homes hot water on tap without firing a stove, a quiet luxury that became a standard fitting.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Hot_water_heater_with_pipe.jpg?width=1024"}, {"name": "Thermostat", "rarity": "uncommon", "id": "thermostat", "subtitle": "Household", "details": "Andrew Ure coined the name in 1830; bimetallic strips that bend with heat became the simple sensing heart of home heating controls.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/PECO_T8532-002.png?width=1024"}, {"name": "Wristwatch", "rarity": "uncommon", "id": "wristwatch", "subtitle": "Household", "details": "Wristlets were novelties until soldiers in the First World War strapped pocket watches to their wrists for a glanceable, hands-free time check.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Rolex_Oyster_Perpetual_with_a_%22Jubliee%22_dial.jpg?width=1024"}, {"name": "Alarm Clock", "rarity": "uncommon", "id": "alarm-clock", "subtitle": "Household", "details": "Levi Hutchins built an alarm for himself in 1787 that rang at 4 a.m. only; adjustable mechanical alarms for everyone else followed a century later.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2010-07-20_Black_windup_alarm_clock_face.jpg?width=1024"}, {"name": "Sunglasses", "rarity": "uncommon", "id": "sunglasses", "subtitle": "Household", "details": "Tinted lenses are old, but Sam Foster's mass-produced 1929 sunglasses, sold on Atlantic City's boardwalk, turned eye protection into fashion.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Allef_Vinicius_2016-10-20_%28Unsplash%29_%28cropped%29.jpg?width=1024"}, {"name": "Backpack", "rarity": "uncommon", "id": "backpack", "subtitle": "Household", "details": "External-frame packs from the 1950s moved loads onto the hips; internal frames and padded straps in the 1960s and 1970s made them everyday carry.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Rucksack1.jpg?width=1024"}, {"name": "Vacuum Flask", "rarity": "uncommon", "id": "vacuum-flask", "subtitle": "Household", "details": "James Dewar's 1892 double-walled vessel with a vacuum gap kept gases liquid for science; as the Thermos bottle it kept soup hot for everyone.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Thermos.JPG?width=1024"}, {"name": "Morse Code", "rarity": "uncommon", "id": "morse-code", "subtitle": "Communication", "details": "Morse and Vail's dot-dash code squeezed letters into clicks; common letters got the shortest signals.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/International_Morse_Code.svg?width=1024"}, {"name": "QWERTY Keyboard", "rarity": "uncommon", "id": "qwerty-keyboard", "subtitle": "Communication", "details": "Sholes arranged QWERTY in the 1870s, spacing common letter pairs so typewriter arms would not jam.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/KB_United_States-NoAltGr.svg?width=1024"}, {"name": "Packet Switching", "rarity": "uncommon", "id": "packet-switching", "subtitle": "Communication", "details": "Baran and Davies, working apart, proposed chopping data into routed blocks - the Internet's core trick.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/PK_Switched_Vs_Circuit_Switched.jpg?width=1024"}, {"name": "Ethernet", "rarity": "uncommon", "id": "ethernet", "subtitle": "Communication", "details": "Metcalfe sketched Ethernet at Xerox PARC in 1973; it wired the world's offices one cable at a time.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ethernet_connector.webp?width=1024"}, {"name": "Hyperlink", "rarity": "uncommon", "id": "hyperlink", "subtitle": "Communication", "details": "Nelson coined 'hypertext' in 1965 and dreamed of linked documents decades before the web linked them.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Hyperlink_example.svg?width=1024"}, {"name": "SMS Texting", "rarity": "uncommon", "id": "sms-texting", "subtitle": "Communication", "details": "The first text message, 'Merry Christmas', was sent in 1992; texts were limited to 160 characters.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Party_SMS.jpg?width=1024"}, {"name": "Video Calling", "rarity": "uncommon", "id": "video-calling", "subtitle": "Communication", "details": "AT&T's Picturephone flopped in 1964; the idea waited fifty years for cheap cameras and fast networks.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Teliris_VL_Modular.JPG?width=1024"}, {"name": "Automatic Telephone Exchange", "rarity": "uncommon", "id": "automatic-telephone-exchange", "subtitle": "Communication", "details": "Undertaker Almon Strowger, suspecting a rival was diverting his calls, invented the automatic exchange.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Uniselector_Stepper_detail.jpg?width=1024"}, {"name": "Undersea Telegraph Cable", "rarity": "uncommon", "id": "undersea-telegraph-cable", "subtitle": "Communication", "details": "After several failures, the first lasting transatlantic telegraph cable entered service in 1866.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Landing_of_the_Atlantic_Cable_of_1866%2C_Heart%27s_Content%2C_Newfoundland.jpg?width=1024"}, {"name": "Cellular Network", "rarity": "uncommon", "id": "cellular-network", "subtitle": "Communication", "details": "Bell Labs engineers proposed cells and frequency reuse in 1947; the first commercial service launched in 1983.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/CellTowerRichmondHill.jpg?width=1024"}, {"name": "QR Code", "rarity": "uncommon", "id": "qr-code", "subtitle": "Communication", "details": "Denso Wave invented the QR code in 1994 to track car parts; it was designed to be read fast at any angle.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/QR_code_for_mobile_English_Wikipedia.svg?width=1024"}, {"name": "Blockchain", "rarity": "uncommon", "id": "blockchain", "subtitle": "Computing", "details": "The 2008 Bitcoin paper chained blocks of records with hashes; each block vouches for the one before.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Storage-how_blockchain_storage_works_mobile.png?width=1024"}, {"name": "Cloud Computing", "rarity": "uncommon", "id": "cloud-computing", "subtitle": "Computing", "details": "Cloud computing rents distant servers by the minute; the idea echoes 1960s time-sharing mainframes.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Cloud_computing.svg?width=1024"}, {"name": "Relational Database", "rarity": "uncommon", "id": "relational-database", "subtitle": "Computing", "details": "Codd's 1970 paper proposed organising data in linked tables, queried with language instead of code.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Relational_Model_2.jpg?width=1024"}, {"name": "Operating System", "rarity": "uncommon", "id": "operating-system", "subtitle": "Computing", "details": "Early computers ran one job at a time; operating systems learned to juggle programs, files and users.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Operating_system_placement.svg?width=1024"}, {"name": "File Compression", "rarity": "uncommon", "id": "file-compression", "subtitle": "Computing", "details": "Lempel and Ziv's 1977-78 algorithms squeezed files by spotting repeats; ZIP and GIF still use their ideas.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/ZIP_File.png?width=1024"}, {"name": "Computer-Aided Design", "rarity": "uncommon", "id": "computer-aided-design", "subtitle": "Computing", "details": "Ivan Sutherland's Sketchpad of 1963 let engineers draw with a light pen directly on a computer screen.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/SketchChair-Screenshot.png?width=1024"}, {"name": "Boolean Logic", "rarity": "uncommon", "id": "boolean-logic", "subtitle": "Computing", "details": "Boole's 1854 algebra of true and false became, a century later, the logic inside every computer circuit.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/ECL_structure_1000.jpg?width=1024"}, {"name": "Machine Learning", "rarity": "uncommon", "id": "machine-learning", "subtitle": "Computing", "details": "Samuel's checkers program of 1959 'learned' from games it played; he popularised the term machine learning.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Example_of_a_deep_neural_network.png?width=1024"}, {"name": "Pascaline", "rarity": "uncommon", "id": "pascaline", "subtitle": "Computing", "details": "Pascal built his toothed-wheel calculator in 1642 to ease his father's tax sums in Rouen; fifty were made.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Pascaline-CnAM%20823-1-IMG%201506-black.jpg?width=1024"}, {"name": "Vaseline", "rarity": "uncommon", "id": "vaseline", "subtitle": "Accident", "details": "Robert Chesebrough saw oil drillers using rod wax, a drill residue, on burns — and refined it into petroleum jelly in 1870.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9e/Bo%C3%AEte_de_vaseline_britannique%2C_1996.180%283%29.jpg/1280px-Bo%C3%AEte_de_vaseline_britannique%2C_1996.180%283%29.jpg"}, {"name": "Worcestershire Sauce", "rarity": "uncommon", "id": "worcestershire-sauce", "subtitle": "Accident", "details": "Lea and Perrins made a sauce to a returned traveller's recipe, disliked it, and left it in a cellar — where ageing made it famous.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/6/65/Dimitri_Torterat_-_Bottle_of_Worcestershire_sauce.jpg/1280px-Dimitri_Torterat_-_Bottle_of_Worcestershire_sauce.jpg"}, {"name": "Nachos", "rarity": "uncommon", "id": "nachos", "subtitle": "Accident", "details": "In 1943 Ignacio Anaya, faced with hungry guests and a bare kitchen, improvised tortillas, cheese and jalapeños under the broiler.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c3/Nachos-cheese_%28cropped%29.jpg/1280px-Nachos-cheese_%28cropped%29.jpg"}, {"name": "Aspartame", "rarity": "uncommon", "id": "aspartame", "subtitle": "Accident", "details": "Chemist James Schlatter licked a finger to turn a page in 1965 and tasted his ulcer-drug compound: a sweetener 200 times sugar's strength.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Green%20Stevia%20Maltodextrin%20extract%20sugar%20packets%20PhilippinesA.jpg?width=1024"}, {"name": "Safety Glass", "rarity": "uncommon", "id": "safety-glass", "subtitle": "Accident", "details": "In 1903 Édouard Bénédictus dropped a flask lined with dried cellulose nitrate; it cracked but held together, suggesting laminated glass.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cb/Windshield-spiderweb.jpg/1280px-Windshield-spiderweb.jpg"}, {"name": "Cellophane", "rarity": "uncommon", "id": "cellophane", "subtitle": "Accident", "details": "Jacques Brandenberger wanted a stain-proof tablecloth coating; the peelable clear film he got in 1908 became packaging instead.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Cellofan.jpg?width=1024"}, {"name": "Scotchgard", "rarity": "uncommon", "id": "scotchgard", "subtitle": "Accident", "details": "At 3M in 1953, Patsy Sherman's experimental mix spilled on an assistant's tennis shoe — and the spot would not wash or wear off.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f3/Martexin_Waxed_Canvas_Water_Resistance.jpg/1280px-Martexin_Waxed_Canvas_Water_Resistance.jpg"}, {"name": "Kevlar", "rarity": "uncommon", "id": "kevlar", "subtitle": "Accident", "details": "Stephanie Kwolek's 1965 polymer solution came out cloudy and thin; persuading the spinneret operator to run it yielded a super-fibre.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e3/Bulletproof_vest_J1.jpg/1280px-Bulletproof_vest_J1.jpg"}, {"name": "Radioactivity", "rarity": "uncommon", "id": "radioactivity", "subtitle": "Accident", "details": "In 1896 Henri Becquerel left uranium salts on a wrapped photographic plate in a drawer; it developed anyway, fogged by invisible rays.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Uranium%20ore%20and%20%22yellowcake%22%20uranium%20concentrate%20at%20the%20Greifswald%20Nuclear%20Power%20Plant%20information%20center.jpg?width=1024"}, {"name": "Polyethylene", "rarity": "uncommon", "id": "polyethylene", "subtitle": "Accident", "details": "ICI chemists found a waxy white solid coating their failed 1933 high-pressure experiment: the world's most common plastic, by leak.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/9/94/Polyethylene_balls5.jpg/1280px-Polyethylene_balls5.jpg"}, {"name": "Champagne", "rarity": "uncommon", "id": "champagne", "subtitle": "Accident", "details": "Legend credits Dom Pérignon with inventing the sparkle, but he likely fought it as a fault; the myth was spread long after his death.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d2/Champagnepour.JPG/1280px-Champagnepour.JPG"}, {"name": "Friction Match", "rarity": "uncommon", "id": "friction-match", "subtitle": "Accident", "details": "John Walker scraped a dried chemical lump off his stirring stick in 1826 and it burst into flame: the first friction match, sold as lights.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/6/60/Friction_d%27une_allumette.jpg/1280px-Friction_d%27une_allumette.jpg"}, {"name": "Ether Anesthesia", "rarity": "uncommon", "id": "ether-anesthesia", "subtitle": "Accident", "details": "Watching revellers shrug off injuries at ether frolics hinted the gas could dull pain; public surgical use followed in 1846.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f0/The_First_Operation_Under_Ether_-_Robert_Hinckley.jpg/1280px-The_First_Operation_Under_Ether_-_Robert_Hinckley.jpg"}, {"name": "Edison's Spirit Phone", "rarity": "uncommon", "id": "edisons-spirit-phone", "subtitle": "Patent", "details": "In 1920 Edison told reporters he was designing a device to speak with the dead. No prototype or evidence of one has ever surfaced.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Edison%20at%20work%20on%20machine%20to%20talk%20with%20dead%20-%20Baltimore%20Sun%201920.jpg"}, {"name": "Edison's Concrete Houses", "rarity": "uncommon", "id": "edisons-concrete-houses", "subtitle": "Patent", "details": "Edison promoted homes cast in a single pour of concrete as cheap, fireproof housing. Few sold, his company lost money, and a handful survive.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Thomas%20Edison%20concrete%20house.jpg"}, {"name": "Ford's Soybean Car", "rarity": "uncommon", "id": "fords-soybean-car", "subtitle": "Patent", "details": "Unveiled in 1941, Ford's experimental car used body panels of soybean-fiber plastic on a steel frame. World War II ended the project.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ford%20HempBodyCar.jpg"}, {"name": "The Dymaxion Car", "rarity": "uncommon", "id": "dymaxion-car", "subtitle": "Patent", "details": "Buckminster Fuller's teardrop Dymaxion car, 1933, seated 11 and steered with its rear wheel. A fatal crash that year ended its prospects.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/1934%20Dymaxion%20(1418438271).jpg?width=1024"}, {"name": "Laser-Pointer Cat Exercise", "rarity": "uncommon", "id": "laser-pointer-cat-exercise", "subtitle": "Patent", "details": "US 5,443,036 (1995) patented the method of exercising a cat by moving a laser-pointer dot for it to chase. Yes, that needed a patent.", "image": "https://media.kasperskycontenthub.com/wp-content/uploads/sites/67/2016/10/10031411/ip4.jpg"}, {"name": "The Toilet Snorkel", "rarity": "uncommon", "id": "toilet-snorkel", "subtitle": "Patent", "details": "US 4,320,756 (1982) lets a person trapped by hotel fire breathe air from a sewer vent — through a tube pushed past the toilet's water trap.", "image": "https://www.patentsdemystified.com/wp-content/uploads/2015/02/New-Picture.jpg"}, {"name": "High-Five Simulator", "rarity": "uncommon", "id": "high-five-simulator", "subtitle": "Patent", "details": "US 5,356,330 (1994) is a spring-loaded mechanical arm for the fan watching the game alone, so no touchdown celebration goes unanswered.", "image": "https://www.strangerdimensions.com/wp-content/uploads/2014/06/high-five-machine.jpg"}, {"name": "Motorized Ice Cream Cone", "rarity": "uncommon", "id": "motorized-ice-cream-cone", "subtitle": "Patent", "details": "US 5,971,829 (1999) motorized the hardest part of dessert: a battery-powered holder rotates the scoop against your outstretched tongue.", "image": "http://www.patentplaques-blog.com/wp-content/uploads/2010/07/icecream.jpg"}, {"name": "The Kissing Shield", "rarity": "uncommon", "id": "kissing-shield", "subtitle": "Patent", "details": "US 5,727,565 (1998) stretched a germ-proof membrane over a heart-shaped frame, for safe kissing. Romance, reportedly, did not survive it.", "image": "https://truthfully.com/wp-content/uploads/2024/09/US5727565-drawings-page-2-1024x1024.png"}, {"name": "Self-Tipping Hat", "rarity": "uncommon", "id": "self-tipping-hat", "subtitle": "Patent", "details": "James Boyle's US 556,248 (1896) hid clockwork in a hat so a bow would lift and rotate it automatically. Politeness, mechanized.", "image": "https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEhEuZjcxyM0Ara6TnRC5bmQg8qXdr7cVISZetFovSsZ1wvUhWwlgaq4dFz2ivGENqK5CPJhubZeKNe6TGPVNLbYOv0e5mjggDkkqK-rrBbq7KQf-vOg7DeRrd-Zvw0ysthY50ZeI7Pex_GbFzwJMfPnMY2aHCJTilUkR7bh1y0Mt2_ujLjCOXrq/s1600/US-Patent-556248-Figure-1.png"}, {"name": "The Moustache Guard", "rarity": "uncommon", "id": "moustache-guard", "subtitle": "Patent", "details": "Virgil Gates' US 176,175 (1876) strapped a small shield over the moustache, held by cords over the ears, to keep soup out of the whiskers.", "image": "https://razors.click/patents/US176175/US176175.jpg"}, {"name": "Dimple-Making Machine", "rarity": "uncommon", "id": "dimple-making-machine", "subtitle": "Patent", "details": "Sold from 1936, this wire-and-knob contraption pressed spring-loaded points into the cheeks to manufacture dimples. It mostly manufactured pain.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Woman%20wearing%20Isabelle%20Gilbert%27s%20Dimple%20Maker%20invention.jpg?width=1024"}, {"name": "Automatic Dog Petter", "rarity": "uncommon", "id": "automatic-dog-petter", "subtitle": "Patent", "details": "Patent filings describe a sensor-triggered mechanical hand that pets a resting dog while a speaker plays its owner's voice.", "image": "https://www.patentsdemystified.com/wp-content/uploads/2015/02/AutoPetterSmallc.jpg"}, {"name": "Centrifugal Birth Machine", "rarity": "uncommon", "id": "centrifugal-birth-machine", "subtitle": "Patent", "details": "US 3,216,423 (1965) proposed strapping a mother to a spinning table so centrifugal force could assist delivery. No hospital adopted it.", "image": "https://www.patentsdemystified.com/wp-content/uploads/2015/02/BabySpinner2.jpg"}, {"name": "Umbrella", "rarity": "common", "id": "umbrella", "subtitle": "Foundational", "details": "Sunshades and rain umbrellas guarded rulers in Egypt, China and India for millennia before the folding umbrella went global.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Beige%20and%20brown%20oil-paper%20umbrella%20on%20the%20edge%20of%20a%20wooden%20house%20in%20Luang%20Prabang%20Laos.jpg?width=1024"}, {"name": "Chopsticks", "rarity": "common", "id": "chopsticks", "subtitle": "Foundational", "details": "Used in China for over 3,000 years, chopsticks began as cooking tools before becoming the everyday utensil of East Asia.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Many-chopsticks.jpg?width=1024"}, {"name": "The Fork", "rarity": "common", "id": "the-fork", "subtitle": "Foundational", "details": "Table forks, used in Byzantium and the Middle East, reached Italy by the 11th century and slowly joined the knife at meals.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/GeorgianSilverForks.jpg?width=1024"}, {"name": "Kiln", "rarity": "common", "id": "kiln", "subtitle": "Foundational", "details": "Enclosed kilns fired pottery hotter and more evenly than open fires, enabling glazed ware, bricks and tiles at scale.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Pottery%20oven%20in%20Nov%C3%A1%20budova%20N%C3%A1rodn%C3%ADho%20muzea%20Prague.jpg?width=1024"}, {"name": "Oil Lamp", "rarity": "common", "id": "oil-lamp", "subtitle": "Foundational", "details": "Stone and clay lamps burning oil with a wick gave households portable light from the Bronze Age into the modern era.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Terracotta%20oil%20lamp%20MET%20DP232.jpg?width=1024"}, {"name": "The Mirror", "rarity": "common", "id": "the-mirror", "subtitle": "Foundational", "details": "Polished obsidian and bronze mirrors reflected faces in Anatolia and Egypt thousands of years before silvered glass.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/8th%20Cent.%20AD%20Tang%20Bronze%20Mirror%2001.jpg?width=1024"}, {"name": "Lock and Key", "rarity": "common", "id": "lock-and-key", "subtitle": "Foundational", "details": "Pin locks of wood and metal guarded Egyptian and Roman doors; keys became both security and status symbols.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Roman%20key%20%28locking%29%20%28FindID%20619316%29.jpg?width=1024"}, {"name": "Sewing Needle", "rarity": "common", "id": "sewing-needle", "subtitle": "Foundational", "details": "Eyed needles of bone and ivory let people stitch fitted clothing tens of thousands of years ago.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Medieval%20or%20Post-Medieval%2C%20Couching%20Needle.%20Treasure%20case%20no.%202020%20T266%20%28FindID%20998187%29.jpg?width=1024"}, {"name": "Fish Hook", "rarity": "common", "id": "fish-hook", "subtitle": "Foundational", "details": "Barbed hooks of bone, shell and bronze turned fishing from spearing and trapping into a portable, patient craft.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Bone%20fish%20hooks%20found%20at%20Russell%20Cave%20%28480267bb-9e03-499a-bb8f-b07650274e30%29.jpg?width=1024"}, {"name": "The Button", "rarity": "common", "id": "the-button", "subtitle": "Foundational", "details": "Buttons fastened clothing in the medieval era after centuries as ornaments, pairing with buttonholes to replace pins and ties.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Cast%20copper%20alloy%20post%20medieval%20buttons%20%28FindID%2078208%29.jpg?width=1024"}, {"name": "The Candle", "rarity": "common", "id": "the-candle", "subtitle": "Foundational", "details": "Tallow and beeswax candles with fibre wicks gave homes steady, portable light for well over a thousand years.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Wax%20candles%20lit.jpg?width=1024"}, {"name": "Rope", "rarity": "common", "id": "rope", "subtitle": "Foundational", "details": "Twisted plant and animal fibres made rope for hauling, sailing and building - among humanity's oldest tools, still essential.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Cordage%20chantier%20de%20l%27Hermione%20Rochefort%20sur%20Mer.jpg?width=1024"}, {"name": "The Saw", "rarity": "common", "id": "the-saw", "subtitle": "Foundational", "details": "Toothed blades of flint, bronze and steel let builders cut timber and stone with a back-and-forth stroke for millennia.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Cassells%20Carpentry.78%20hand%20saw.png?width=1024"}, {"name": "The Nail", "rarity": "common", "id": "the-nail", "subtitle": "Foundational", "details": "Forged metal nails, standardised by Roman builders, fastened ships, roofs and furniture across the ancient world.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Group%20of%20varied%20Roman%20Iron%20Nails%20%28FindID%20515376%29.jpg?width=1024"}, {"name": "The Broom", "rarity": "common", "id": "the-broom", "subtitle": "Foundational", "details": "Bound twigs and fibres swept floors in ancient homes; the flat broom design was refined in the late 1700s.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Besom%20%28PSF%29.png?width=1024"}, {"name": "The Comb", "rarity": "common", "id": "the-comb", "subtitle": "Foundational", "details": "Combs of bone, ivory and wood groomed hair and picked fibres in Egypt and Mesopotamia over 5,000 years ago.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Cincinnati%20Art%20Museum%20-%20Comb.jpg?width=1024"}, {"name": "The Fan", "rarity": "common", "id": "the-fan", "subtitle": "Foundational", "details": "Hand fans of feathers, palm and paper cooled faces and stoked fires in Egypt, China and Japan for thousands of years.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Fan%2C%20Japanese%2C%201700s%2C%20bird%20motifs%20made%20of%20feathers%20-%20Fan%20Room%2C%20Alc%C3%A1zar%20of%20Seville%2C%20Spain%20-%20DSC07321.JPG?width=1024"}, {"name": "The Spoon", "rarity": "common", "id": "the-spoon", "subtitle": "Foundational", "details": "Shells, wood and bone spoons served food in prehistoric homes long before metal cutlery sets standardised the table.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Silver%20spoon%20and%20fork%20MET%20DP223162.jpg?width=1024"}, {"name": "Fired Brick", "rarity": "common", "id": "fired-brick", "subtitle": "Foundational", "details": "Sun-dried mudbrick came first; kiln-firing, practised in the Indus Valley by around 3000 BCE, made bricks that could outlast empires.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ancient%20site%20at%20Lothal13.jpg?width=1024"}, {"name": "Safety Match", "rarity": "common", "id": "safety-match", "subtitle": "Industrial", "details": "Swedish safety matches of the 1850s split the chemicals between match head and striking strip, so they light only on the box.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/003_Welth%C3%B6lzer_anagoria.JPG?width=1024"}, {"name": "Electromagnet", "rarity": "common", "id": "electromagnet", "subtitle": "Industrial", "details": "William Sturgeon's 1825 coil of wire around an iron horseshoe lifted nine pounds — magnetism at the flick of a current.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Electromagnet-with-9V-battery.jpg?width=1024"}, {"name": "Gas Lighting", "rarity": "common", "id": "gas-lighting", "subtitle": "Industrial", "details": "William Murdoch lit his house with coal gas in the 1790s; gaslight soon lined the streets of whole cities.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Gas_street_light%2C_Marlborough_Street%2C_Belfast_-_geograph.org.uk_-_573944.jpg?width=1024"}, {"name": "Arc Lamp", "rarity": "common", "id": "arc-lamp", "subtitle": "Industrial", "details": "Humphry Davy's early 1800s arc leapt between charcoal rods in a blaze brighter than any candle or oil lamp.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Xenon_short_arc_1.jpg?width=1024"}, {"name": "Kerosene", "rarity": "common", "id": "kerosene", "subtitle": "Industrial", "details": "Abraham Gesner's 1850s kerosene, distilled from coal and later petroleum, gave lamps a clean, cheap fuel.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/A_kerosene_lamp_produced_by_the_factory_of_Karlskrona_Lampfabrik_in_Sweden_c._1890s.jpg?width=1024"}, {"name": "Canning", "rarity": "common", "id": "canning", "subtitle": "Industrial", "details": "Nicolas Appert won a French prize in 1810 for preserving food in sealed, heated jars — Napoleon needed fed armies.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/FMIB_34482_Making_Salmon_Cans.jpeg?width=1024"}, {"name": "Portland Cement", "rarity": "common", "id": "portland-cement", "subtitle": "Industrial", "details": "Joseph Aspdin's 1824 patent named his cement for Portland stone; it became the glue of the modern world.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Portland_Cement_Bags.jpg?width=1024"}, {"name": "Reinforced Concrete", "rarity": "common", "id": "reinforced-concrete", "subtitle": "Industrial", "details": "Embedding iron or steel bars in concrete, patented by Joseph Monier in 1867, let it bend without breaking.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Talbruecke-Bruenn_2005-08-04.jpg?width=1024"}, {"name": "Carburetor", "rarity": "common", "id": "carburetor", "subtitle": "Industrial", "details": "The carburettor mixes air and fuel into the fine mist an early petrol engine needs to run smoothly.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Holley_2280.jpg?width=1024"}, {"name": "Celluloid", "rarity": "common", "id": "celluloid", "subtitle": "Industrial", "details": "John Wesley Hyatt's 1870 celluloid, made chasing a billiard-ball prize, became film stock and combs alike.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/ButterflyDancebis.jpg?width=1024"}, {"name": "Rayon", "rarity": "common", "id": "rayon", "subtitle": "Industrial", "details": "Patented in the 1890s, rayon spun dissolved wood pulp into 'artificial silk' for affordable finery.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Rayon_synthesis.webm?width=1024"}, {"name": "Oil Well", "rarity": "common", "id": "oil-well", "subtitle": "Industrial", "details": "Edwin Drake's 1859 Titusville well, drilled like a water well, struck oil and started the petroleum age.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/West_Texas_Pumpjack.JPG?width=1024"}, {"name": "Clinical Thermometer", "rarity": "common", "id": "clinical-thermometer", "subtitle": "Medicine", "details": "Thomas Allbutt's short thermometer of 1866 took a temperature in minutes, not the twenty his predecessors needed.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Mercury_Thermometer.jpg?width=480"}, {"name": "Hearing Aid", "rarity": "common", "id": "hearing-aid", "subtitle": "Medicine", "details": "Ear trumpets funnelled sound for centuries; electric hearing aids arrived in the early 1900s.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Hearing_aid_20080620.jpg?width=1024"}, {"name": "Pacemaker", "rarity": "common", "id": "pacemaker", "subtitle": "Medicine", "details": "The first fully implantable pacemaker was fitted in Sweden in 1958, keeping a steady rhythm for a failing heart.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/St_Jude_Medical_pacemaker_with_ruler.jpg?width=1024"}, {"name": "CT Scan", "rarity": "common", "id": "ct-scan", "subtitle": "Medicine", "details": "Godfrey Hounsfield's 1971 scanner combined X-rays with computing to slice the body into cross-sections.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lachine_Hospital_CT_Scanner.jpg?width=1024"}, {"name": "MRI", "rarity": "common", "id": "mri", "subtitle": "Medicine", "details": "MRI, developed in the 1970s, images soft tissue with magnets and radio waves — no ionising radiation.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/MRI-Philips.JPG?width=1024"}, {"name": "Artificial Heart", "rarity": "common", "id": "artificial-heart", "subtitle": "Medicine", "details": "The Jarvik-7 of 1982 was the first artificial heart implanted as a permanent replacement.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/CardioWest%E2%84%A2_temporary_Total_Artificial_Heart.jpg?width=1024"}, {"name": "Defibrillator", "rarity": "common", "id": "defibrillator", "subtitle": "Medicine", "details": "A controlled electric shock can restart a heart's rhythm; portable defibrillators spread from the 1950s.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Defibrillation_Electrode_Position.jpg?width=1024"}, {"name": "Ultrasound Imaging", "rarity": "common", "id": "ultrasound-imaging", "subtitle": "Medicine", "details": "Adapted from sonar in the 1950s, ultrasound watches a beating heart or unborn baby with sound alone.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Sonographer_doing_pediatric_echocardiography.JPG?width=1024"}, {"name": "Escalator", "rarity": "common", "id": "escalator", "subtitle": "Industrial", "details": "Patented as an 'inclined elevator' by Jesse Reno in 1892; Otis's moving staircases soon carried shoppers and station crowds by the million.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Metro%20Centrum%20Nauki%20Kopernik%20Schody-AB.jpg?width=1024"}, {"name": "Pencil", "rarity": "common", "id": "pencil", "subtitle": "Household", "details": "Graphite sticks were wrapped in wood after a Borrowdale deposit was found in the 1560s; glued cedar slats made the modern pencil by the 1800s.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Pencils_hb.jpg?width=1024"}, {"name": "Bottle Opener", "rarity": "common", "id": "bottle-opener", "subtitle": "Household", "details": "Crown caps arrived in 1892 and openers followed within two years; the church key levered caps and later punched triangular holes in cans.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Bottle_Opener_Metal_For_Beer_Edited_2020.jpg?width=1024"}, {"name": "Potato Peeler", "rarity": "common", "id": "potato-peeler", "subtitle": "Household", "details": "Swivel-blade peelers patented in the 1920s float over bumps and round corners, wasting less potato than a straight knife ever could.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Peeler_01_Pengo.jpg?width=1024"}, {"name": "Cheese Grater", "rarity": "common", "id": "cheese-grater", "subtitle": "Household", "details": "Francois Boullier is credited with a tin grater in 1540s France; the four-sided box grater multiplied the edges for shreds of every size.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Kuechenreibe_%28fcm%29.jpg?width=1024"}, {"name": "Clothespin", "rarity": "common", "id": "clothespin", "subtitle": "Household", "details": "David Smith's 1853 clothespin added a spring and two levers so laundry gripped the line without squeezing the fabric in a single peg.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Clothes_pegs_2016-05-25_02.jpg?width=1024"}, {"name": "Ironing Board", "rarity": "common", "id": "ironing-board", "subtitle": "Household", "details": "Folding ironing boards were patented repeatedly in the 1800s; Sarah Boone's 1892 design added a narrow, padded shape made for sleeves.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Board%2C_ironing_%28AM_2007.52.1-7%29.jpg?width=1024"}, {"name": "Garden Hose", "rarity": "common", "id": "garden-hose", "subtitle": "Household", "details": "Stitched leather hoses served early fire brigades; vulcanised rubber and later vinyl turned the hose into a light garden staple.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Garden_hose.jpg?width=1024"}, {"name": "Sprinkler", "rarity": "common", "id": "sprinkler", "subtitle": "Household", "details": "Oscillating lawn sprinklers patented in the 1890s swept a fan of water back and forth, sparing gardeners the endless hose-dragging.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Impact_Sprinkler_Mechanism_2.jpg?width=1024"}, {"name": "Cotton Swab", "rarity": "common", "id": "cotton-swab", "subtitle": "Household", "details": "Leo Gerstenzang watched his wife wind cotton on a toothpick in 1923 and machine-made the ready swab, sold first as a baby-care item.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/White_menbo.jpg?width=1024"}, {"name": "Paper Towel", "rarity": "common", "id": "paper-towel", "subtitle": "Household", "details": "Arthur Scott's company turned a mis-cut batch of tissue into disposable towels in 1907 after a teacher's cold remedy gave him the idea.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Paper_towel.jpg?width=1024"}, {"name": "Facial Tissue", "rarity": "common", "id": "facial-tissue", "subtitle": "Household", "details": "Kimberly-Clark's 1924 tissues were marketed to remove cold cream; readers wrote in about their handkerchief use and the advertising pivoted.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Box_of_Scotties_tissues.jpg?width=1024"}, {"name": "Disposable Lighter", "rarity": "common", "id": "disposable-lighter", "subtitle": "Household", "details": "Cheap butane lighters of the early 1970s put a regulated flame, a flint wheel and thousands of lights into a throwaway plastic tube.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/White_lighter_with_flame.JPG?width=1024"}, {"name": "Extension Cord", "rarity": "common", "id": "extension-cord", "subtitle": "Household", "details": "Harvey Hubbell's separable plugs and sockets from 1904 let appliances unplug safely, and extension leads carried power across the room.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Extension_cord.JPG?width=1024"}, {"name": "Power Strip", "rarity": "common", "id": "power-strip", "subtitle": "Household", "details": "Multi-socket strips multiplied the wall outlet as homes filled with lamps, radios and chargers; surge protection was added to guard them.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Tricklestar_Plug_Strip.jpg?width=1024"}, {"name": "Mop", "rarity": "common", "id": "mop", "subtitle": "Household", "details": "Thomas Stewart's 1893 patent clamped a replaceable mop head that a lever could wring, so hands stayed out of the dirty water.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Mop%2C_three_different_mop_handles.jpg?width=1024"}, {"name": "Cellulose Sponge", "rarity": "common", "id": "cellulose-sponge", "subtitle": "Household", "details": "DuPont's 1940s cellulose sponge copied the sea sponge's thirst in a factory-made block that outsold and outlasted the natural harvest.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/%C3%89ponge_type_3_%281%29.jpg?width=1024"}, {"name": "Measuring Cup", "rarity": "common", "id": "measuring-cup", "subtitle": "Household", "details": "Fannie Farmer's 1896 cookbook demanded level, standard measures; graduated cups turned a cook's handful into a repeatable recipe.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Simple_Measuring_Cup.jpg?width=1024"}, {"name": "Whisk", "rarity": "common", "id": "whisk", "subtitle": "Household", "details": "Bundles of twigs whisked eggs for centuries; wire balloon whisks patented in the 1800s folded in far more air with far less effort.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Schneebesen1.JPG?width=1024"}, {"name": "Spatula", "rarity": "common", "id": "spatula", "subtitle": "Household", "details": "Flexible silicone blades replaced rigid turners in the late 1900s, scraping bowls clean and surviving oven heat that melted older plastics.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Kitchen_utensils-01.jpg?width=1024"}, {"name": "Laundry Detergent", "rarity": "common", "id": "laundry-detergent", "subtitle": "Household", "details": "Synthetic detergents developed in 1916 Germany, short on soap fats, cleaned in hard water where ordinary soap left grey scum.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Pralni_pra%C5%A1ek.JPG?width=1024"}, {"name": "Toothpaste Tube", "rarity": "common", "id": "toothpaste-tube", "subtitle": "Household", "details": "Washington Sheffield put toothpaste in a collapsible metal tube in 1892, borrowing the paint tube so paste stayed fresh and portable.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Toothpasteonbrush.jpg?width=1024"}, {"name": "Dustpan", "rarity": "common", "id": "dustpan", "subtitle": "Household", "details": "Lloyd Ray's 1897 patent added a handle to the flat pan so sweepers could gather dirt standing up instead of crouching with a plate.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Stofferenblik.jpg?width=1024"}, {"name": "Fly Swatter", "rarity": "common", "id": "fly-swatter", "subtitle": "Household", "details": "Robert Montgomery's 1900 patent fixed wire mesh to a handle as the fly killer; plastic swatters still follow his flat, fast design.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Fly_swatter.jpg?width=1024"}, {"name": "Mousetrap", "rarity": "common", "id": "mousetrap", "subtitle": "Household", "details": "William Hooker's 1894 spring-loaded snap trap set the pattern: a wire bail, a hair trigger and a very bad day for the mouse.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Victor-Mousetrap.jpg?width=1024"}, {"name": "Lint Roller", "rarity": "common", "id": "lint-roller", "subtitle": "Household", "details": "Nicholas McKay's 1956 sticky-paper roller, devised with his wife Helen, peeled lint, hair and dust off suits in a few quick passes.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lint_remover.png?width=1024"}, {"name": "Shoehorn", "rarity": "common", "id": "shoehorn", "subtitle": "Household", "details": "Shoehorns appear in the 1400s as shoeing horns; the curved blade slips a heel into a tight shoe without crushing the shoe's back.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Shoehorn-800.jpg?width=1024"}, {"name": "Safety Pin", "rarity": "common", "id": "safety-pin", "subtitle": "Household", "details": "Walter Hunt invented the safety pin in 1849 to settle a small debt, coiling a spring and adding a clasp that covers the sharp point.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Safety_Pin.jpg?width=1024"}, {"name": "Ice Cube Tray", "rarity": "common", "id": "ice-cube-tray", "subtitle": "Household", "details": "Lloyd Copeman's flexible rubber tray of 1933 let home freezers pop out cubes one by one instead of chipping at a solid block.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ice_cube_tray.jpg?width=1024"}, {"name": "Garlic Press", "rarity": "common", "id": "garlic-press", "subtitle": "Household", "details": "Karl Zysset's 1950s press forced cloves through a grid of holes, mincing garlic in one squeeze without a board, a knife or sticky fingers.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Garlic_Press_and_Garlic.jpg?width=1024"}, {"name": "Lunch Box", "rarity": "common", "id": "lunch-box", "subtitle": "Household", "details": "Workers carried meals in tobacco tins for decades; purpose-made metal lunch boxes with handles and a thermos hump arrived in the 1900s.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Harry_S._Truman_Lunch_Box.jpg?width=1024"}, {"name": "Christmas Lights", "rarity": "common", "id": "christmas-lights", "subtitle": "Household", "details": "Edward Johnson hand-wired 80 red, white and blue bulbs on his tree in 1882; ready-made strings soon replaced candles on branches.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Christmas_Tree_-_Flickr_-_anantal.jpg?width=1024"}, {"name": "Egg Slicer", "rarity": "common", "id": "egg-slicer", "subtitle": "Household", "details": "Willy Abel, who also devised the bread slicer, patented the wire egg slicer in 1911; one press yields even slices for salads and sandwiches.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Eierschneider.jpg?width=1024"}, {"name": "Chip Clip", "rarity": "common", "id": "chip-clip", "subtitle": "Household", "details": "Spring clips reseal opened snack bags against stale air; the simple hinge and grip turned a half-eaten bag into a stored one.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Laura_Fine_2018_state_senate_campaign_chip_clip.jpg?width=1024"}, {"name": "Shorthand", "rarity": "common", "id": "shorthand", "subtitle": "Communication", "details": "Pitman published his phonetic shorthand in 1837; clerks suddenly wrote as fast as people spoke.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Shorthand_%28PSF%29.png?width=1024"}, {"name": "Esperanto", "rarity": "common", "id": "esperanto", "subtitle": "Communication", "details": "Zamenhof published Esperanto in 1887 hoping a shared second language would help strangers get along.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Flag_of_Esperanto.svg?width=1024"}, {"name": "Caller ID", "rarity": "common", "id": "caller-id", "subtitle": "Communication", "details": "Caller ID spread in the 1980s and 90s, ending the mystery - and the menace - of the anonymous ring.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Arduino_telephone_caller_ID_unit.jpg?width=1024"}, {"name": "Teleprinter", "rarity": "common", "id": "teleprinter", "subtitle": "Communication", "details": "Teleprinters typed wire messages straight onto paper for newsrooms and offices - the network, at typewriter speed.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Teletype_machine_with_tape_punch_-_National_Electronics_Museum_-_DSC00212.JPG?width=1024"}, {"name": "Emoji", "rarity": "common", "id": "emoji", "subtitle": "Communication", "details": "Kurita designed the first 176 emoji for Japanese phones in 1999; they grew into a global picture alphabet.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Emoji_u1f600.svg?width=1024"}, {"name": "Hashtag", "rarity": "common", "id": "hashtag", "subtitle": "Communication", "details": "Chris Messina proposed the # symbol for grouping messages in 2007; the humble hash became an organiser.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/WikiProject_Writing_%28%40WP_Writing%29_Tweet_-_Why_edit_Wikipedia%3F.jpg?width=1024"}, {"name": "Semaphore Flags", "rarity": "common", "id": "semaphore-flags", "subtitle": "Communication", "details": "Navies spelled messages with two flags from the 1800s; scouts and lifeguards still learn the alphabet.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/US_Navy_051129-N-0685C-007_Quartermaster_Seaman_Ryan_Ruona_signals_with_semaphore_flags_during_a_replenishment_at_sea.jpg?width=1024"}, {"name": "Adhesive Postage Stamp", "rarity": "common", "id": "adhesive-postage-stamp", "subtitle": "Communication", "details": "The Penny Black of 1840 put the cost on the sender: stick it on, and the letter simply went.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Penny_black.jpg?width=1024"}, {"name": "Podcast", "rarity": "common", "id": "podcast", "subtitle": "Communication", "details": "Podcasting took off in 2004 when audio blogs learned to arrive by subscription, like radio on demand.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Serial_Podcast.jpg?width=1024"}, {"name": "Wiki", "rarity": "common", "id": "wiki", "subtitle": "Communication", "details": "Ward Cunningham launched the first wiki in 1995 so programmers could edit a website as easily as read it.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Wikipedia-logo-v2.svg?width=1024"}, {"name": "Blog", "rarity": "common", "id": "blog", "subtitle": "Communication", "details": "Early weblogs were hand-kept lists of interesting links; by the late 1990s anyone could publish daily.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/BlogActive.com_Screenshot_2004.jpg?width=1024"}, {"name": "Conference Call", "rarity": "common", "id": "conference-call", "subtitle": "Communication", "details": "Telephone conferences linked scattered voices by the mid-1900s; the meeting learned to travel.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Conferencecallphone.jpg?width=1024"}, {"name": "Emoticon", "rarity": "common", "id": "emoticon", "subtitle": "Communication", "details": "Scott Fahlman proposed :-) and :-( in 1982 so readers of a campus message board could tell jokes from facts.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Smiley_Face_Emoticon.svg?width=1024"}, {"name": "Word Processor", "rarity": "common", "id": "word-processor", "subtitle": "Computing", "details": "WordStar and its rivals turned typing into editing in the late 1970s; the delete key ate the eraser's job.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Libreoffice_writer_20120206055154.png?width=1024"}, {"name": "CAPTCHA", "rarity": "common", "id": "captcha", "subtitle": "Computing", "details": "CAPTCHAs arrived in 2000 to tell humans from bots; ironically, solving them trained the bots' cousins.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Captcha.jpg?width=1024"}, {"name": "The Computer Bug", "rarity": "common", "id": "the-computer-bug", "subtitle": "Computing", "details": "Operators found a moth in Harvard's Mark II in 1947 and taped it in the logbook: the first actual computer bug.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/First_Computer_Bug%2C_1945.jpg?width=1024"}, {"name": "GIF", "rarity": "common", "id": "gif", "subtitle": "Computing", "details": "CompuServe's GIF format of 1987, built for slow modems, outlived its maker as the web's loop of choice.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Earth-spinning-rotating-animation-40.gif?width=1024"}, {"name": "Computer Password", "rarity": "common", "id": "computer-password", "subtitle": "Computing", "details": "MIT's time-sharing system gave users passwords in 1961; a printout theft soon caused the first password breach.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Mediawiki_1.25_sign_in_form.png?width=1024"}, {"name": "Copy and Paste", "rarity": "common", "id": "copy-and-paste", "subtitle": "Computing", "details": "Larry Tesler championed cut, copy and paste at Xerox PARC in the 1970s - and campaigned against modes.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Using_Clipboard_in_mobilEcho_Application.png?width=1024"}, {"name": "Undo", "rarity": "common", "id": "undo", "subtitle": "Computing", "details": "Undo forgives: the ability to reverse an action crept into editors in the 1970s and became a reflex.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Undo-redo.jpg?width=1024"}, {"name": "Software Easter Egg", "rarity": "common", "id": "software-easter-egg", "subtitle": "Computing", "details": "Warren Robinett hid his name in Atari's Adventure in 1979, the most famous early software Easter egg.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Warren_Robinett%2C_2015.jpg?width=1024"}, {"name": "Spam Filter", "rarity": "common", "id": "spam-filter", "subtitle": "Computing", "details": "As junk email flooded inboxes in the 1990s, filters learned to fight back with word statistics.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Spammed-mail-folder.png?width=1024"}, {"name": "Chewing Gum", "rarity": "common", "id": "chewing-gum", "subtitle": "Accident", "details": "Thomas Adams tried to turn chicle into rubber in 1869, failed, then popped a piece in his mouth and built a gum business instead.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/Vintage_Gumball_Machine_%282552026699%29.jpg/1280px-Vintage_Gumball_Machine_%282552026699%29.jpg"}, {"name": "Paper Towels", "rarity": "common", "id": "paper-towels", "subtitle": "Accident", "details": "In 1907 Arthur Scott faced a trainload of paper rolled too thick for toilet tissue — and sold it as disposable towels instead.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1f/Roll_of_Paper_Towels.jpg/1280px-Roll_of_Paper_Towels.jpg"}, {"name": "Rubber Eraser", "rarity": "common", "id": "rubber-eraser", "subtitle": "Accident", "details": "In 1770 Joseph Priestley found a ball of rubber rubbed out pencil marks better than bread crumbs, naming the eraser for its motion.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2f/Pink_Pearl_eraser.jpg/1280px-Pink_Pearl_eraser.jpg"}, {"name": "Buffalo Wings", "rarity": "common", "id": "buffalo-wings", "subtitle": "Accident", "details": "By the usual account, Teressa Bellissimo improvised wings in sauce at Buffalo's Anchor Bar in 1964 for her son's hungry friends.", "image": "https://upload.wikimedia.org/wikipedia/commons/5/51/Buffalo_wings-01.jpg"}, {"name": "Chimichanga", "rarity": "common", "id": "chimichanga", "subtitle": "Accident", "details": "Legend has it a burrito was dropped into a deep fryer at Tucson's El Charro and a near-curse was softened into 'chimichanga'.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a8/Chimichangas.jpg/1280px-Chimichangas.jpg"}, {"name": "Ice Cream Sundae", "rarity": "common", "id": "ice-cream-sundae", "subtitle": "Accident", "details": "Its origin is disputed — Ithaca and Two Rivers both claim the 1890s tale of a soda served with syrup when plain sodas were banned.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9d/Ice_cream_sundae.jpg/1280px-Ice_cream_sundae.jpg"}, {"name": "Fanta", "rarity": "common", "id": "fanta", "subtitle": "Accident", "details": "Cut off from Coke syrup in 1940, Coca-Cola's German branch improvised a drink from whey and apple pomace leftovers: Fanta.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cd/Fanta_Orange_Glass_Bottle.jpg/1280px-Fanta_Orange_Glass_Bottle.jpg"}, {"name": "Chocolate Brownie", "rarity": "common", "id": "chocolate-brownie", "subtitle": "Accident", "details": "One story blames a cook who forgot the baking powder in a chocolate cake in 1893; the dense, fudgy result became the brownie.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/Chocolate_brownies_without_table.jpg/1280px-Chocolate_brownies_without_table.jpg"}, {"name": "Linoleum", "rarity": "common", "id": "linoleum", "subtitle": "Accident", "details": "Frederick Walton noticed in 1855 that spilled linseed oil had dried into a tough, rubbery skin — the germ of linoleum flooring.", "image": "https://upload.wikimedia.org/wikipedia/commons/e/e9/Black_and_green_linoleum.jpg"}, {"name": "Pyroceram", "rarity": "common", "id": "pyroceram", "subtitle": "Accident", "details": "In 1953 Donald Stookey accidentally overheated a glass plate at Corning; it turned into a white ceramic tougher than the glass was.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Corningware%20casserole%20dishes.jpg?width=1024"}, {"name": "Mayonnaise", "rarity": "common", "id": "mayonnaise", "subtitle": "Accident", "details": "One story credits a French chef in Mahón in 1756, whisking up egg and oil when the cream ran out; the sauce took the town's name.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/6/60/Mayonnaise_%281%29.jpg/1280px-Mayonnaise_%281%29.jpg"}, {"name": "Thousand Island Dressing", "rarity": "common", "id": "thousand-island-dressing", "subtitle": "Accident", "details": "Legend says a fisherman's wife in the Thousand Islands mixed the dressing from what was on hand; a dinner guest spread its fame.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3d/Thousand-Island-Dressing_%28Salad%29.jpg/1280px-Thousand-Island-Dressing_%28Salad%29.jpg"}, {"name": "Eggs Benedict", "rarity": "common", "id": "eggs-benedict", "subtitle": "Accident", "details": "Rival New York hotels both claim it: a hungover broker's off-menu order, or a chef's improvisation for regulars who wanted new.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/1/12/Eggs_Benedict_at_Delmonico%27s.jpg/1280px-Eggs_Benedict_at_Delmonico%27s.jpg"}, {"name": "Cobb Salad", "rarity": "common", "id": "cobb-salad", "subtitle": "Accident", "details": "By the standard account, Bob Cobb raided the Brown Derby's kitchen late one night in 1937 and chopped the leftovers into a salad.", "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/9/90/Chicken_Cobb_Salad_-_PINSTACK_Plano_%282015-04-10_19.42.14_by_Nan_Palmero%29.jpg/1280px-Chicken_Cobb_Salad_-_PINSTACK_Plano_%282015-04-10_19.42.14_by_Nan_Palmero%29.jpg"}, {"name": "Sealed Crustless Sandwich", "rarity": "common", "id": "sealed-crustless-sandwich", "subtitle": "Patent", "details": "US 6,004,596 (1999) patented a crustless PB&J sealed by crimping; its broad claims were later cancelled in reexamination.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Smucker%27s%20Uncrustable%20%288126536249%29.jpg?width=1024"}, {"name": "The Patented Comb-Over", "rarity": "common", "id": "patented-comb-over", "subtitle": "Patent", "details": "US 4,022,227 (1977) patented combing long hair over a bald spot in three directions. It later won its inventors an Ig Nobel Prize.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/US4022227.png?width=1024"}, {"name": "The Swing Patent", "rarity": "common", "id": "swing-patent", "subtitle": "Patent", "details": "US 6,368,227 (2002) patented a schoolboy's method of swinging side-to-side on a swing. The Patent Office later cancelled all its claims.", "image": "http://www.patentplaques-blog.com/wp-content/uploads/2010/07/swing.jpg"}, {"name": "The Patented Stick", "rarity": "common", "id": "patented-stick", "subtitle": "Patent", "details": "US 6,360,693 (2002) claimed an 'animal toy' that is, in the drawings, a stick a dog can fetch. Reexamination cancelled every claim.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Dalmatian%20fetching%20a%20stick.jpg?width=1024"}, {"name": "Beerbrella", "rarity": "common", "id": "beerbrella", "subtitle": "Patent", "details": "US 6,637,447 (2003), the Beerbrella, clips a five-to-seven-inch umbrella to a drink to keep the sun off it. Shade, at last, for beer.", "image": "https://media.kasperskycontenthub.com/wp-content/uploads/sites/67/2016/10/10031412/ip3.jpg"}, {"name": "Flatulence Deodorizer", "rarity": "common", "id": "flatulence-deodorizer", "subtitle": "Patent", "details": "US 6,313,371 (2001) is a charcoal pad worn inside underwear to deodorize flatulence. Related fart-filtering underwear won an Ig Nobel.", "image": "https://strachanip.co.uk/wp-content/uploads/2021/12/2021-12-10-2-1024x663.png"}, {"name": "Santa Claus Detector", "rarity": "common", "id": "santa-claus-detector", "subtitle": "Patent", "details": "Thomas Cane's US 5,523,741 (1996) is a stocking that lights up when its trip cord is pulled — proof, for children, that Santa has visited.", "image": "https://images.squarespace-cdn.com/content/v1/5efadb7d16ee51271a48f46e/1fb15c00-9b04-4942-8174-d761a860dd23/Patent+Christmas.jpg"}, {"name": "Full-Body Teleportation", "rarity": "common", "id": "full-body-teleportation", "subtitle": "Patent", "details": "A 2006 patent application (US 2006/0071122) proposed teleporting people through hyperspace with a wormhole generator. It was abandoned.", "image": "http://patentimages.storage.googleapis.com/US20060071122A1/US20060071122A1-20060406-D00001.png"}, {"name": "Chicken Eye Protectors", "rarity": "common", "id": "chicken-eye-protectors", "subtitle": "Patent", "details": "Andrew Jackson Jr.'s US 730,918 (1903) put tiny spectacles on chickens so flockmates could not peck their eyes out. Sears sold them.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Eye%20Glasses%20For%20Chickens.png"}, {"name": "Anti-Eating Face Mask", "rarity": "common", "id": "anti-eating-face-mask", "subtitle": "Patent", "details": "Lucy Barmby's US 4,344,424 (1982) strapped a wire cage over the mouth so the wearer could talk but not eat. A diet aid, technically.", "image": "https://www.oddee.com/wp-content/uploads/_media/imgs/articles2/a96675_a445_helpforovereaters.jpg"}, {"name": "Plutonium Pacemaker", "rarity": "common", "id": "plutonium-pacemaker", "subtitle": "Patent", "details": "In the 1970s, some pacemakers were powered by plutonium-238 and built to run for decades. A few patients carried them for over 30 years.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/HD.17.051%20(11950696403).jpg?width=1024"}, {"name": "Violet-Ray Wand", "rarity": "common", "id": "violet-ray-wand", "subtitle": "Patent", "details": "Violet-ray devices zapped patients with high-voltage 'medical electricity' and were sold as cure-alls until regulators shut makers down.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Violet%20wand.JPG"}, {"name": "The Monowheel", "rarity": "common", "id": "monowheel", "subtitle": "Patent", "details": "Inventors have patented one-wheeled cycles since 1869, with the rider sitting inside the wheel. Steering and braking remain exciting.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/McLean%20Monowheel%20Lane%20Motor%20Museum.jpg?width=1024"}, {"name": "The Umbrella Hat", "rarity": "common", "id": "umbrella-hat", "subtitle": "Patent", "details": "An umbrella, worn as a hat: hands-free shade patented in various forms for over a century, adopted mainly by fishermen and novelty fans.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Robert%20W.%20Patten%20wearing%20his%20Umbrella%20Hat%2C%20circa%201890-1910.jpg?width=1024"}, {"name": "The Steam Man", "rarity": "common", "id": "steam-man", "subtitle": "Patent", "details": "In 1868 Zadoc Dederick patented a steam-powered mechanical man meant to pull a carriage — a robot chauffeur, eighty years early.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Zadoc%20Dederick%20and%20Isaac%20Grass'%20Steam%20Man%20schematic.png"}, {"name": "Project Pigeon", "rarity": "common", "id": "project-pigeon", "subtitle": "Patent", "details": "B. F. Skinner trained pigeons to steer a bomb by pecking at a target screen. It worked in tests; officials declined to use it.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Project%20Orcon%20and%20Skinner's%20pigeons%20playing%20table-tennis.jpg"}, {"name": "Amphibious Bicycle", "rarity": "common", "id": "amphibious-bicycle", "subtitle": "Patent", "details": "Inventors have patented bicycles that paddle across lakes since the 1800s. None has yet made the bicycle outsell the boat.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Amfibiefiets%20Amphibious%20bicycle.jpg"}, {"name": "Edison's Talking Doll", "rarity": "common", "id": "edisons-talking-doll", "subtitle": "Patent", "details": "Edison's 1890 phonograph dolls recited nursery rhymes in scratchy voices that frightened children. He recalled them within weeks.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Edison%20Phonograph%20Doll%2001.jpg"}]});
